// ── i18n helper (module-level, lee el idioma en vivo desde localStorage) ──
const _EN = () => { try { return (localStorage.getItem("nexo-lang")||"en")==="en"; } catch { return true; } };

const SUPABASE_URL  = "https://glvrzrtatekuuhwtzzhd.supabase.co";
const SUPABASE_KEY  = "sb_publishable_1CCvWAO3iqcFZmcqvUdlZg_rOdSZZcl";
// FIX CRÍTICO (Sesión 11): supabase-js usa navigator.locks ("lock:nexotrade-session")
// para serializar la auth. Si una operación (p.ej. setSession fire-and-forget) nunca
// resuelve, el lock queda tomado PARA SIEMPRE y TODAS las queries (posts, perfiles,
// mensajes…) se quedan colgadas sin error. Lock custom sin deadlock: ejecuta directo.
const _noDeadlockLock = async (_name, _acquireTimeout, fn) => await fn();
const supabase      = createClient(SUPABASE_URL, SUPABASE_KEY, {
  auth: {
    persistSession: true,
    autoRefreshToken: true,
    detectSessionInUrl: true,
    storageKey: 'nexotrade-session',
    lock: _noDeadlockLock,
  }
});

// ── OAUTH SOCIAL (Google / Apple) ───────────────────────────────────────────
// Lanza el flujo OAuth de Supabase. Al volver, detectSessionInUrl + onAuthStateChange
// inician sesión automáticamente. REQUIERE activar el proveedor en el panel de
// Supabase (Authentication → Providers) con sus credenciales (Google OAuth Client,
// Apple Service ID) y añadir la URL del sitio en Redirect URLs.
async function nexoOAuth(provider){
  const NAME = provider==="google"?"Google":provider==="facebook"?"Facebook":provider==="apple"?"Apple":provider;
  try{
    const redirectTo = (typeof window!=="undefined" && window.location && window.location.origin)
      ? window.location.origin : "https://nexotradeia.com";
    const { error } = await supabase.auth.signInWithOAuth({
      provider,
      options:{ redirectTo, queryParams: provider==="google" ? { prompt:"select_account" } : undefined }
    });
    if(error){
      console.error("[oauth] "+provider+":", error.message);
      alert((_EN()?"Couldn't sign in with ":"No se pudo iniciar con ")+NAME+". "+
            (_EN()?"The provider isn't enabled in Supabase yet. (":"El proveedor aún no está activado en Supabase. (")+error.message+")");
    }
  }catch(e){
    console.error("[oauth] "+provider+":", e?.message||e);
    alert("Error al conectar con "+NAME+".");
  }
}

// ── WEB PUSH (Sesión 12) ──────────────────────────────────────────────────────
const VAPID_PUBLIC_KEY = "BHEABdZbcAr7ka890b3KOA15ZwgKVBrMxMWxUw217-tE-BmDz11HFjzWzPbuoHmm7-Rbh6m9NPZD5zjevUCHtOY";
const _urlB64ToUint8 = (s)=>{const p="=".repeat((4-s.length%4)%4);const b=(s+p).replace(/-/g,"+").replace(/_/g,"/");const r=atob(b);return Uint8Array.from([...r].map(c=>c.charCodeAt(0)));};
// Suscribe este navegador a Web Push y guarda la suscripción en Supabase
async function subscribeWebPush(user){
  try{
    if(!("serviceWorker" in navigator) || !("PushManager" in window)) return false;
    if(Notification.permission!=="granted") return false;
    const reg = await navigator.serviceWorker.ready;
    let sub = await reg.pushManager.getSubscription();
    if(!sub){
      sub = await reg.pushManager.subscribe({userVisibleOnly:true, applicationServerKey:_urlB64ToUint8(VAPID_PUBLIC_KEY)});
    }
    const j = sub.toJSON();
    if(!j?.endpoint || !j?.keys?.p256dh) return false;
    await supabase.from("push_subscriptions").upsert({
      user_id: user?.id || null,
      endpoint: j.endpoint,
      p256dh: j.keys.p256dh,
      auth: j.keys.auth,
      user_agent: (navigator.userAgent||"").slice(0,180),
    },{onConflict:"endpoint"});
    return true;
  }catch(e){ return false; }
}

// Pista de instalación para Web Push según el dispositivo:
//   "ios"     → iPhone/iPad sin la PWA instalada → push REQUIERE instalar (Safari iOS).
//   "android" → Android sin instalar → push funciona con permiso; instalar mejora la fiabilidad.
//   null      → escritorio o ya instalada → no hace falta aviso.
function pushDeviceHint(){
  try{
    const ua = navigator.userAgent || "";
    const isIOS = /iPad|iPhone|iPod/.test(ua) || (navigator.platform==="MacIntel" && navigator.maxTouchPoints>1);
    const isAndroid = /Android/.test(ua);
    const standalone = (window.navigator && window.navigator.standalone===true) ||
                       (window.matchMedia && window.matchMedia("(display-mode: standalone)").matches);
    if(standalone) return null;
    if(isIOS) return "ios";
    if(isAndroid) return "android";
    return null;
  }catch{ return null; }
}

