                        <div style={{flex:1,display:"flex",alignItems:"flex-start"}}>
                          {!isPos&&<div title={`${v}%`} style={{width:"100%",height:h,borderRadius:"0 0 3px 3px",background:"#DC2626"}}/>}
                        </div>
