function GifPicker({onSelect,onClose,onText,lang="es"}){
  const isEN = lang==="en";
  const [tab,setTab]         = useState("gif");
  const [q,setQ]             = useState("");
  const [gifs,setGifs]       = useState([]);
  const [loading,setLoading] = useState(false);
  const [apiSrc,setApiSrc]   = useState("…");

  const search = (query) => {
    setLoading(true);
    // Si no hay búsqueda, usar un término aleatorio para que se vean GIFs nuevos cada vez
    const SEEDS = ["money","cash","rich","bull market","stocks up","crypto moon","celebrate","diamond hands","stonks","to the moon","bitcoin","wealth","trading","profits","money rain","make it rain","millionaire","wall street","gold bars","stock market","cash money","get rich","payday","jackpot","money money money","rich vibes","counting money"];
    const term = query.trim() || SEEDS[Math.floor(Math.random()*SEEDS.length)];
    const url = `/api/gifs?q=${encodeURIComponent(term)}`;
    fetch(url)
      .then(r=>r.json())
      .then(d=>{ setGifs(d.gifs&&d.gifs.length>0?d.gifs:GIF_CLIENT_FALLBACK); setApiSrc(d.source||"fallback"); setLoading(false); })
      .catch(()=>{ setGifs(GIF_CLIENT_FALLBACK); setApiSrc("fallback"); setLoading(false); });
  };

  useEffect(()=>{ if(tab==="gif") search(""); },[tab]);

  const TAGS = ["💰 money","💵 cash","🤑 rich","💸 dollars","📈 bull","📉 bear","📊 stocks","💹 stonks","🏦 wallstreet","🤑 profit","🪙 bitcoin","🥇 gold","💰 millionaire","🚀 moon","💎 hodl","crypto","🎉 celebrate"];
  const tabs = [{k:"gif",l:"GIF 🎞️"},{k:"emoji",l:"Emojis 😎"},{k:"reaction",l:"Frases ⚡"},{k:"sticker",l:"Stickers 🎨"}];

  return(
    <>
    {/* Backdrop para cerrar al tocar fuera */}
    <div onClick={onClose} style={{position:"fixed",inset:0,background:"rgba(0,0,0,0.45)",zIndex:9998}}/>
    <div style={{position:"fixed",bottom:0,left:0,right:0,maxWidth:720,margin:"0 auto",background:C.surface||"#fff",border:`1px solid ${C.border}`,borderRadius:"18px 18px 0 0",boxShadow:"0 -12px 48px rgba(0,0,0,0.28)",zIndex:9999,overflow:"hidden"}}>
      {/* Tabs */}
      <div style={{display:"flex",borderBottom:`1px solid ${C.border}`,background:C.card2||"#f8fafc"}}>
        {tabs.map(t=>(
          <button key={t.k} onClick={()=>setTab(t.k)}
            style={{flex:1,padding:"9px 4px",border:"none",background:"none",cursor:"pointer",fontSize:11,fontWeight:700,color:tab===t.k?C.accent:C.muted,borderBottom:tab===t.k?`2px solid ${C.accent}`:"2px solid transparent",transition:"all 0.15s"}}>
            {t.l}
          </button>
        ))}
        <button onClick={onClose} style={{padding:"9px 12px",border:"none",background:"none",cursor:"pointer",fontSize:16,color:C.muted}}>✕</button>
      </div>

      <div style={{padding:10}}>
        {/* ── GIF TAB ── */}
        {tab==="gif"&&<>
          <div style={{display:"flex",gap:6,marginBottom:8}}>
            <input value={q} onChange={e=>setQ(e.target.value)}
              onKeyDown={e=>{if(e.key==="Enter"){e.preventDefault();search(q);}}}
              placeholder={isEN?"🔍 Search: money, cash, bull...":"🔍 Buscar: dinero, cash, bull..."} autoFocus
              style={{flex:1,border:`1px solid ${C.border}`,borderRadius:9,padding:"7px 11px",fontSize:12,outline:"none",background:C.card2||"#f8fafc",color:C.text}}/>
            <button onClick={()=>search(q)} style={{background:C.accent,border:"none",borderRadius:9,padding:"7px 14px",color:"#fff",fontWeight:700,fontSize:12,cursor:"pointer"}}>⟳</button>
          </div>
          <div style={{display:"flex",gap:4,flexWrap:"wrap",marginBottom:8}}>
            {TAGS.map(tag=>{const w=tag.split(" ").pop();return(
              <button key={tag} onClick={()=>{setQ(w);search(w);}}
                style={{background:"rgba(15,76,129,0.08)",border:"1px solid rgba(15,76,129,0.2)",borderRadius:20,padding:"2px 9px",fontSize:10,cursor:"pointer",color:C.accentText,fontWeight:600}}>{tag}</button>
            );})}
          </div>
          {loading?<div style={{textAlign:"center",padding:"20px 0",color:C.muted,fontSize:13}}>🎞️ {isEN?"Searching GIFs...":"Buscando GIFs..."}</div>:(
            <div style={{display:"grid",gridTemplateColumns:"repeat(3,1fr)",gap:4,maxHeight:250,overflowY:"auto"}}>
              {gifs.map(g=>(
                <div key={g.id} style={{borderRadius:8,overflow:"hidden",cursor:"pointer",height:94,background:C.card2||"#f1f5f9",position:"relative"}}
                  onClick={()=>onSelect(g.full||g.preview)}>
                  <img src={g.preview} alt={g.title} loading="lazy" style={{width:"100%",height:"100%",objectFit:"cover",display:"block"}} onError={e=>{e.target.parentElement.style.display="none";}}/>
                </div>
              ))}
            </div>
          )}
          <div style={{fontSize:9,color:C.muted2,textAlign:"right",marginTop:4}}>Powered by {apiSrc==="giphy"?"Giphy":"Tenor"}</div>
        </>}

        {/* ── EMOJI TAB ── */}

        {tab==="emoji"&&<>
          <div style={{fontSize:11,color:C.muted,marginBottom:8,fontWeight:600}}>{isEN?"Tap an emoji to add it to your post:":"Toca un emoji para añadirlo a tu post:"}</div>
          <div style={{display:"grid",gridTemplateColumns:"repeat(8,1fr)",gap:4,maxHeight:240,overflowY:"auto"}}>
            {TRADING_EMOJIS.map(e=>(
              <button key={e} onClick={()=>{ onText&&onText(e+" "); onClose(); }}
                style={{background:"none",border:`1px solid ${C.border}`,borderRadius:8,padding:"7px 4px",cursor:"pointer",fontSize:20,transition:"all 0.12s",lineHeight:1}}
                onMouseEnter={ev=>ev.currentTarget.style.background=C.card2||"#f0f9ff"}
                onMouseLeave={ev=>ev.currentTarget.style.background="none"}>{e}</button>
            ))}
          </div>
        </>}

        {/* ── FRASES RÁPIDAS TAB ── */}
        {tab==="reaction"&&<>
          <div style={{fontSize:11,color:C.muted,marginBottom:8,fontWeight:600}}>{isEN?"Insert a quick phrase in your post:":"Inserta una frase rápida en tu post:"}</div>
          <div style={{display:"flex",flexDirection:"column",gap:5,maxHeight:260,overflowY:"auto"}}>
            {QUICK_REACTIONS_FN(isEN).map(r=>(
              <button key={r.label} onClick={()=>{ onText&&onText(r.text); onClose(); }}
                style={{background:"none",border:`1px solid ${C.border}`,borderRadius:10,padding:"9px 12px",cursor:"pointer",textAlign:"left",fontSize:12,color:C.text,fontWeight:600,transition:"all 0.12s"}}
                onMouseEnter={ev=>{ev.currentTarget.style.background=C.card2||"#f0f9ff";ev.currentTarget.style.borderColor=C.accent;}}
                onMouseLeave={ev=>{ev.currentTarget.style.background="none";ev.currentTarget.style.borderColor=C.border;}}>
                {r.label}
              </button>
            ))}
          </div>
        </>}

        {/* ── STICKERS TAB ── */}
        {tab==="sticker"&&<>
          <div style={{fontSize:11,color:C.muted,marginBottom:8,fontWeight:600}}>{isEN?"Trading stickers for your post:":"Stickers de trading para tu post:"}</div>
          <div style={{display:"grid",gridTemplateColumns:"repeat(2,1fr)",gap:8,maxHeight:260,overflowY:"auto"}}>
            {STICKERS.map(s=>(
              <button key={s.id} onClick={()=>{ onText&&onText(s.emoji+" "+s.text+" "); onClose(); }}
                style={{background:s.bg,border:"none",borderRadius:12,padding:"14px 10px",cursor:"pointer",color:"#fff",fontWeight:900,fontSize:13,letterSpacing:0.5,transition:"transform 0.12s,opacity 0.12s",display:"flex",alignItems:"center",gap:8}}
                onMouseEnter={ev=>{ev.currentTarget.style.transform="scale(1.03)";ev.currentTarget.style.opacity="0.9";}}
                onMouseLeave={ev=>{ev.currentTarget.style.transform="scale(1)";ev.currentTarget.style.opacity="1";}}>
                <span style={{fontSize:22}}>{s.emoji}</span>
                <span>{s.text}</span>
              </button>
            ))}
          </div>
        </>}
      </div>
    </div>
    </>
  );
}

// ── TICKER PAGE (página completa de una acción) ───────────────────────────────
function SentimentHistoryPremium({ticker, isPremium, onNeedPremium, lang="es"}){
  const [open, setOpen] = useState(false); // colapsado por defecto
  const seed=ticker.split("").reduce((a,c)=>a+c.charCodeAt(0),0);
  const rnd=(offset,min,max)=>Math.min(max,Math.max(min,Math.round(50+Math.sin((seed+offset)*0.9)*20+Math.cos((seed+offset)*0.5)*12)));

  // Periodos: 1 día siempre visible, el resto premium
  const periods=[
    {label:(lang==="en"?"24h ago":"Hace 24h"),    key:"1d",  bull:rnd(1,35,75), free:true},
    {label:(lang==="en"?"1 wk ago":"Hace 1 sem"),  key:"1w",  bull:rnd(2,30,78), free:false},
    {label:(lang==="en"?"1 mo ago":"Hace 1 mes"),  key:"1m",  bull:rnd(3,28,80), free:false},
    {label:(lang==="en"?"3 mo ago":"Hace 3 meses"),key:"3m",  bull:rnd(5,25,82), free:false},
    {label:(lang==="en"?"6 mo ago":"Hace 6 meses"),key:"6m",  bull:rnd(8,22,85), free:false},
    {label:(lang==="en"?"1 yr ago":"Hace 1 año"),  key:"1y",  bull:rnd(13,20,85),free:false},
  ];

  return(
    <div style={{background:C.surface,border:`1px solid ${C.border}`,borderRadius:16,overflow:"hidden",marginBottom:20}}>
      {/* Header — clic para expandir/colapsar */}
      <div onClick={()=>setOpen(o=>!o)} style={{padding:"13px 18px",background:"linear-gradient(135deg,rgba(15,94,104,0.07),rgba(15,76,129,0.04))",borderBottom:open?`1px solid ${C.border}`:"none",display:"flex",alignItems:"center",justifyContent:"space-between",cursor:"pointer",userSelect:"none"}}>
        <div style={{display:"flex",alignItems:"center",gap:8}}>
          <span style={{fontSize:17}}>🧭</span>
          <div>
            <div style={{fontWeight:800,fontSize:14,color:C.text}}>Sentimiento del mercado</div>
            <div style={{fontSize:11,color:C.muted}}>Toca para {open?"ocultar":"ver"} el historial de ${ticker}</div>
          </div>
        </div>
        <div style={{display:"flex",alignItems:"center",gap:8}}>
          {isPremium
            ? <span style={{background:"linear-gradient(135deg,#E0B64B,#C8901F)",color:"#1B1303",borderRadius:20,padding:"3px 10px",fontSize:10,fontWeight:800}}>✦ PREMIUM</span>
            : <button onClick={e=>{e.stopPropagation();onNeedPremium();}} style={{background:"linear-gradient(135deg,#C8901F,#8A5E10)",color:"#fff",border:"none",borderRadius:8,padding:"5px 12px",fontSize:11,fontWeight:800,cursor:"pointer"}}>✦ PREMIUM</button>
          }
          {/* Flecha animada */}
          <span style={{fontSize:16,color:C.muted,display:"inline-block",transition:"transform 0.25s",transform:open?"rotate(180deg)":"rotate(0deg)",lineHeight:1}}>▾</span>
        </div>
      </div>

      {/* Contenido — solo visible cuando open=true */}
      {open && (
        <>
          {/* Filas de periodos */}
          <div>
            {periods.map(({label,key,bull,free},i)=>{
              const visible=free||isPremium;
              const isBull=bull>=50;
              return(
                <div key={key} style={{display:"flex",alignItems:"center",gap:12,padding:"13px 18px",borderBottom:i<periods.length-1?`1px solid ${C.border}`:"none",background:free&&i===0?"rgba(0,229,143,0.02)":"transparent"}}>
                  {/* Etiqueta */}
                  <div style={{width:110,fontSize:12,color:C.muted,fontWeight:600,flexShrink:0}}>{label}</div>

                  {visible?(
                    <>
                      {/* Pill alcista/bajista */}
                      <div style={{background:isBull?"rgba(0,229,143,0.1)":"rgba(255,77,106,0.1)",border:`1px solid ${isBull?"rgba(0,229,143,0.3)":"rgba(255,77,106,0.3)"}`,borderRadius:20,padding:"4px 12px",fontSize:12,fontWeight:800,color:isBull?C.bull:C.bear,minWidth:80,textAlign:"center",flexShrink:0}}>
                        {isBull?"🐂 Alcista":"🐻 Bajista"}
                      </div>
                      {/* Barra de progreso */}
                      <div style={{flex:1,height:8,background:C.card2,borderRadius:20,overflow:"hidden"}}>
                        <div style={{width:`${bull}%`,height:"100%",background:isBull?"linear-gradient(90deg,#00E58F,#00c49a)":"linear-gradient(90deg,#FF4D6A,#cc3355)",borderRadius:20,transition:"width 0.6s ease"}}/>
                      </div>
                      {/* Porcentaje */}
                      <div style={{fontSize:12,fontWeight:800,color:isBull?C.bull:C.bear,fontFamily:"monospace",minWidth:38,textAlign:"right"}}>{bull}%</div>
                    </>
                  ):(
                    <>
                      {/* Bloqueado */}
                      <div style={{background:"rgba(15,94,104,0.08)",border:"1px solid rgba(15,94,104,0.2)",borderRadius:20,padding:"4px 14px",fontSize:11,fontWeight:800,color:"#0F5E68",flexShrink:0,display:"flex",alignItems:"center",gap:5}}>
                        🔒 Premium
                      </div>
                      <div style={{flex:1,height:8,background:`repeating-linear-gradient(90deg,rgba(15,94,104,0.1) 0px,rgba(15,94,104,0.1) 8px,transparent 8px,transparent 14px)`,borderRadius:20}}/>
                      <button onClick={e=>{e.stopPropagation();onNeedPremium();}} style={{fontSize:10,fontWeight:700,color:"#0F5E68",background:"transparent",border:"none",cursor:"pointer",whiteSpace:"nowrap",textDecoration:"underline"}}>Ver →</button>
                    </>
                  )}
                </div>
              );
            })}
          </div>
          {!isPremium&&(
            <div style={{padding:"12px 18px",background:"linear-gradient(135deg,rgba(15,94,104,0.06),rgba(245,158,11,0.04))",borderTop:`1px solid ${C.border}`,textAlign:"center"}}>
              <span style={{fontSize:12,color:C.muted}}>{lang==="en"?"Unlock the full sentiment history with ":"Desbloquea el sentimiento histórico completo con "}</span>
              <span onClick={onNeedPremium} style={{fontSize:12,color:"#0F5E68",fontWeight:800,cursor:"pointer"}}>NexoTrade PREMIUM ✦</span>
            </div>
          )}
        </>
      )}
    </div>
  );
}

// ── CHART — SVG nativo, prueba proxy luego Yahoo Finance directo ──────────────
function TVChart({ticker,lang="es"}){
  const [candles, setCandles] = useState([]);
  const [status,  setStatus]  = useState("loading");

  useEffect(()=>{
    let alive = true;
    setStatus("loading");
    setCandles([]);

    const parseYahoo = (d) => {
      const result = d?.chart?.result?.[0];
      if(!result) return null;
      const ts = result.timestamp||[];
      const q  = result.indicators?.quote?.[0]||{};
      const arr = ts.map((t,i)=>({time:t,open:q.open?.[i],high:q.high?.[i],low:q.low?.[i],close:q.close?.[i]}))
                    .filter(c=>c.open&&c.close);
      return arr.length ? arr : null;
    };

    const run = async () => {
      // Intento 1: nuestro proxy
      try{
        const r = await fetch(`/api/chart?ticker=${encodeURIComponent(ticker)}&range=6mo&interval=1d`);
        if(r.ok){
          const d = await r.json();
          if(d.candles?.length){ if(alive){setCandles(d.candles.slice(-90));setStatus("ok");} return; }
        }
      }catch(e){}

      // Intento 2: Yahoo Finance directo (funciona en la mayoría de regiones)
      try{
        const r = await fetch(`https://query1.finance.yahoo.com/v8/finance/chart/${ticker}?interval=1d&range=6mo&includePrePost=false`,
          {headers:{"Accept":"application/json"}});
        const d = await r.json();
        const arr = parseYahoo(d);
        if(arr){ if(alive){setCandles(arr.slice(-90));setStatus("ok");} return; }
      }catch(e){}

      // Intento 3: endpoint alternativo Yahoo
      try{
        const r = await fetch(`https://query2.finance.yahoo.com/v8/finance/chart/${ticker}?interval=1d&range=6mo`);
        const d = await r.json();
        const arr = parseYahoo(d);
        if(arr){ if(alive){setCandles(arr.slice(-90));setStatus("ok");} return; }
      }catch(e){}

      if(alive) setStatus("error");
    };
    run();
    return ()=>{ alive=false; };
  },[ticker]);

  if(status==="loading") return(
    <div style={{height:260,display:"flex",alignItems:"center",justifyContent:"center",background:"var(--c-surface)",gap:10}}>
      <div style={{width:20,height:20,border:"2.5px solid var(--c-border)",borderTopColor:"#0F4C81",borderRadius:"50%",animation:"nexo-spin 0.8s linear infinite"}}/>
      <span style={{color:"var(--c-muted)",fontSize:12}}>Loading {ticker}...</span>
    </div>
  );

  if(status==="error"||!candles.length) return(
    <div style={{height:260,display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",gap:14,background:"var(--c-surface)"}}>
      <span style={{fontSize:36}}>📊</span>
      <span style={{color:"#64748b",fontSize:13,fontWeight:600}}>No data for {ticker}</span>
      <a href={`https://finance.yahoo.com/quote/${ticker}`} target="_blank" rel="noopener noreferrer"
        style={{color:"#0F4C81",fontSize:12,fontWeight:700,textDecoration:"none",background:"rgba(15,76,129,0.08)",padding:"7px 18px",borderRadius:8,border:"1px solid rgba(15,76,129,0.2)"}}>
        Ver en Yahoo Finance →
      </a>
    </div>
  );

  // ── SVG line chart ────────────────────────────────────────────
  const W=600, H=230, pl=8, pr=56, pt=12, pb=22;
  const closes = candles.map(c=>c.close);
  const minP   = Math.min(...closes);
  const maxP   = Math.max(...closes);
  const range  = maxP - minP || 1;
  const xS = i => pl + (i/(candles.length-1||1))*(W-pl-pr);
  const yS = p => pt + (1-(p-minP)/range)*(H-pt-pb);

  const linePath = closes.map((p,i)=>`${i===0?"M":"L"}${xS(i).toFixed(1)},${yS(p).toFixed(1)}`).join(" ");
  const areaPath = linePath+` L${xS(closes.length-1).toFixed(1)},${(H-pb).toFixed(1)} L${pl},${(H-pb).toFixed(1)} Z`;
  const isUp     = closes[closes.length-1] >= closes[0];
  const col      = isUp ? "#22c55e" : "#ef4444";
  const pct      = (((closes[closes.length-1]-closes[0])/closes[0])*100).toFixed(2);
  const gradId   = `g_${ticker.replace(/[^a-z0-9]/gi,"")}`;

  // 3 horizontal grid lines + price labels
  const gridVals = [0.2, 0.5, 0.8].map(r=>minP+range*r);

  return(
    <div style={{background:"var(--c-surface)",userSelect:"none"}}>
      {/* Header mini stats */}
      <div style={{display:"flex",alignItems:"center",gap:12,padding:"8px 14px 4px",borderBottom:"1px solid var(--c-border)"}}>
        <span style={{fontFamily:"monospace",fontWeight:900,fontSize:18,color:"var(--c-text)"}}>{closes[closes.length-1]?.toLocaleString("en-US",{minimumFractionDigits:2,maximumFractionDigits:2})}</span>
        <span style={{background:isUp?"rgba(34,197,94,0.1)":"rgba(239,68,68,0.1)",color:col,fontWeight:700,fontSize:12,padding:"2px 8px",borderRadius:6}}>{isUp?"+":""}{pct}%</span>
        <span style={{color:"#94a3b8",fontSize:11,marginLeft:"auto"}}>{lang==="en"?"Last 90 days":"Últimos 90 días"}</span>
      </div>
      {/* SVG */}
      <svg viewBox={`0 0 ${W} ${H}`} style={{width:"100%",height:230,display:"block"}}>
        <defs>
          <linearGradient id={gradId} x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stopColor={col} stopOpacity="0.18"/>
            <stop offset="100%" stopColor={col} stopOpacity="0.02"/>
          </linearGradient>
        </defs>
        {/* Grid */}
        {gridVals.map((v,i)=>(
          <g key={i}>
            <line x1={pl} x2={W-pr} y1={yS(v).toFixed(1)} y2={yS(v).toFixed(1)} style={{stroke:"var(--c-border)"}} strokeWidth="1"/>
            <text x={W-pr+6} y={yS(v)+4} fontSize="9" style={{fill:"var(--c-muted)"}}>{v>=1000?v.toFixed(0):v.toFixed(2)}</text>
          </g>
        ))}
        {/* Area */}
        <path d={areaPath} fill={`url(#${gradId})`}/>
        {/* Line */}
        <path d={linePath} fill="none" stroke={col} strokeWidth="1.8" strokeLinejoin="round" strokeLinecap="round"/>
        {/* Last price dot */}
        <circle cx={xS(closes.length-1).toFixed(1)} cy={yS(closes[closes.length-1]).toFixed(1)} r="3" fill={col}/>
        <text x={W-pr+6} y={yS(closes[closes.length-1])+4} fontSize="10" fill={col} fontWeight="700">
          {closes[closes.length-1]>=1000?closes[closes.length-1].toFixed(0):closes[closes.length-1].toFixed(2)}
        </text>
        {/* X axis dates */}
        {[0, Math.floor(candles.length/2), candles.length-1].map(i=>(
          <text key={i} x={xS(i)} y={H-6} fontSize="9" style={{fill:"var(--c-muted)"}} textAnchor="middle">
            {candles[i]?.time ? new Date(candles[i].time*1000).toLocaleDateString("es",{month:"short",day:"numeric"}) : ""}
          </text>
        ))}
      </svg>
      <div style={{padding:"2px 14px 8px",textAlign:"right",fontSize:10,color:"var(--c-muted2,var(--c-muted))"}}>Datos: Yahoo Finance</div>
    </div>
  );
}

function TickerPage({ticker,posts=[],onClose,lang="es",user,onPost,onNeedAuth,isPremium=false,onNeedPremium,onRepost}){
  const [quote,setQuote]=useState(null);
  const [loadingQ,setLoadingQ]=useState(true);
  const [showChart,setShowChart]=useState(true);
  const [metric,setMetric]=useState(null);   // fundamentos (P/E, div, crecimiento) Finnhub
  const [cnews,setCnews]=useState(null);      // noticias recientes Finnhub
  useEffect(()=>{
    setMetric(null); setCnews(null);
    try{
      fetch(`https://finnhub.io/api/v1/stock/metric?symbol=${ticker}&metric=all&token=${FINNHUB_KEY}`).then(r=>r.json()).then(d=>setMetric((d&&d.metric)?d.metric:{})).catch(()=>setMetric({}));
      const f=d=>d.toISOString().slice(0,10);
      fetch(`https://finnhub.io/api/v1/company-news?symbol=${ticker}&from=${f(new Date(Date.now()-30*864e5))}&to=${f(new Date())}&token=${FINNHUB_KEY}`).then(r=>r.json()).then(d=>setCnews(Array.isArray(d)?d.slice(0,4):[])).catch(()=>setCnews([]));
    }catch(_){ setMetric({}); setCnews([]); }
  },[ticker]);

  const tkPosts=posts.filter(p=>
    p.ticker===ticker||
    (p.text?.toUpperCase().includes(`$${ticker}`))||
    (p.text?.toUpperCase().includes(`@${ticker}`))
  );
  const bullN=tkPosts.filter(p=>p.sentiment==="bull").length;
  const bearN=tkPosts.filter(p=>p.sentiment==="bear").length;
  const total=bullN+bearN;
  const bullPct=total>0?Math.round(bullN/total*100):50;

  useEffect(()=>{
    setLoadingQ(true);
    fetch(`https://finnhub.io/api/v1/quote?symbol=${ticker}&token=${FINNHUB_KEY}`)
      .then(r=>r.json()).then(q=>{setQuote(q);setLoadingQ(false);}).catch(()=>setLoadingQ(false));
  },[ticker]);

  const price=quote?.c||0;
  const chg=quote?.dp||0;
  const chgAbs=quote?.d||0;

  return(
    <div>
      {/* Header */}
      <div style={{display:"flex",alignItems:"center",gap:12,marginBottom:18,flexWrap:"wrap"}}>
        <button onClick={onClose}
          style={{background:"transparent",border:`1px solid ${C.border}`,borderRadius:9,padding:"7px 14px",cursor:"pointer",color:C.muted,fontSize:13,fontWeight:600,display:"flex",alignItems:"center",gap:5}}>
          ← Volver
        </button>
        <div style={{background:chg>=0?C.bullBg:C.bearBg,borderRadius:10,padding:"8px 18px"}}>
          <span style={{fontWeight:900,fontSize:20,fontFamily:"monospace",color:chg>=0?C.bull:C.bear}}>${ticker}</span>
        </div>
        {!loadingQ&&price>0&&(
          <div>
            <div style={{fontWeight:800,fontSize:22,fontFamily:"monospace",color:C.text}}>
              ${price>=1000?price.toLocaleString("en",{minimumFractionDigits:0,maximumFractionDigits:0}):price.toFixed(2)}
            </div>
            <div style={{fontWeight:700,fontSize:13,color:chg>=0?C.bull:C.bear}}>
              {chg>=0?"+":""}{chg.toFixed(2)}% ({chg>=0?"+":""}{chgAbs.toFixed(2)})
            </div>
          </div>
        )}
        <div style={{marginLeft:"auto",textAlign:"right"}}>
          <div style={{fontSize:11,color:C.muted,marginBottom:4}}>Sentimiento NexoTrade</div>
          <div style={{display:"flex",alignItems:"center",gap:6}}>
            <span style={{color:C.bull,fontWeight:700,fontSize:12}}>{bullPct}% 🐂</span>
            <div style={{width:60,height:5,background:C.bearBg,borderRadius:20,overflow:"hidden"}}>
              <div style={{width:`${bullPct}%`,height:"100%",background:C.bull,borderRadius:20}}/>
            </div>
            <span style={{color:C.bear,fontWeight:700,fontSize:12}}>{100-bullPct}% 🐻</span>
          </div>
          <div style={{fontSize:10,color:C.muted2,marginTop:2}}>{total} votos de la comunidad</div>
        </div>
      </div>

      {/* Cajón para escribir posts sobre este ticker */}
      <div style={{marginBottom:16}}>
        <NewPost user={user} onPost={onPost} onNeedAuth={onNeedAuth} lang={lang} defaultTicker={ticker}/>
      </div>

      {/* TradingView Chart con toggle */}
      <div style={{background:C.surface,border:`1px solid ${C.border}`,borderRadius:14,overflow:"hidden",marginBottom:20}}>
        <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",padding:"10px 16px",borderBottom:showChart?`1px solid ${C.border}`:"none"}}>
          <span style={{fontWeight:700,fontSize:13,color:C.text}}>📊 {_EN()?"Chart":"Gráfico"} ${ticker}</span>
          <button onClick={()=>setShowChart(v=>!v)}
            style={{background:"rgba(15,76,129,0.08)",border:"1px solid rgba(15,76,129,0.2)",borderRadius:8,padding:"5px 14px",cursor:"pointer",color:"#0F4C81",fontSize:12,fontWeight:700,display:"flex",alignItems:"center",gap:5,transition:"all 0.15s"}}
            onMouseEnter={e=>e.currentTarget.style.background="rgba(15,76,129,0.15)"}
            onMouseLeave={e=>e.currentTarget.style.background="rgba(15,76,129,0.08)"}>
            {showChart ? "▲ Ocultar" : "▼ Mostrar"}
          </button>
        </div>
        {showChart&&<TVChart ticker={ticker} lang={lang}/>}
      </div>

      {/* ── INFORME DE ANALISTAS IA — Premium (lo que pagan) ── */}
      {(function(){
        var isEN=lang==="en";
        var mover=(typeof ALL_MOVERS_POOL!=="undefined"?ALL_MOVERS_POOL:[]).find(function(m){return m.ticker===ticker;});
        var bull=mover?mover.bull:(chg>=0?(60+Math.min(28,Math.round(Math.abs(chg)*4))):(42-Math.min(26,Math.round(Math.abs(chg)*4))));
        bull=Math.max(8,Math.min(95,bull)); var bearPct=100-bull;
        var rating=bull>=78?(isEN?"Strong Buy":"Compra Fuerte"):bull>=62?(isEN?"Buy":"Compra"):bull>=45?(isEN?"Hold":"Mantener"):bull>=30?(isEN?"Sell":"Vender"):(isEN?"Strong Sell":"Venta Fuerte");
        var rColor=bull>=62?"#16A34A":bull>=45?"#F59E0B":"#DC2626";
        var nAn=32+(ticker.charCodeAt(0)%18);
        var buyN=Math.round(nAn*bull/100), sellN=Math.round(nAn*bearPct/100*0.55), holdN=Math.max(0,nAn-buyN-sellN);
        var target=price>0?price*(1+(bull-50)/100*0.55):0;
        var upside=price>0?Math.round((target-price)/price*100):null;
        var whyTxt=mover?(isEN?mover.whyEn:mover.why):"";
        var reasons=whyTxt?whyTxt.split(/\.\s+/).filter(Boolean).map(function(s){return s.replace(/\.$/,"")+".";}):[];
        var bullF=reasons.length?reasons:[isEN?"Constructive analyst momentum and sector tailwinds support the thesis.":"Momentum constructivo de analistas y viento de cola del sector respaldan la tesis."];
        var bearF=[isEN?"Valuation premium and broad-market volatility are the key risks.":"La prima de valoración y la volatilidad del mercado son los riesgos clave.", isEN?"A miss on guidance could trigger profit-taking.":"Un fallo en las previsiones podría desencadenar toma de ganancias."];
        var Pill=function(t,c){return <span style={{fontSize:10.5,fontWeight:800,color:c,background:c+"15",border:"1px solid "+c+"33",borderRadius:7,padding:"3px 9px",letterSpacing:0.2}}>{t}</span>;};
        return (
        <div style={{background:C.surface,border:`1px solid ${C.border}`,borderRadius:16,padding:"18px 18px 16px",marginBottom:20,position:"relative",overflow:"hidden"}}>
          <div style={{position:"absolute",top:0,left:0,right:0,height:3,background:"linear-gradient(90deg,#7C3AED,#1A56DB,#16A34A)"}}/>
          {/* Header */}
          <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:14,flexWrap:"wrap",gap:8}}>
            <div style={{display:"flex",alignItems:"center",gap:8}}>
              <svg width="18" height="18" viewBox="0 0 24 24" fill="#1A56DB"><path d="M12 2l1.55 4.65L18 8l-4.45 1.35L12 14l-1.55-4.65L6 8l4.45-1.35L12 2z"/></svg>
              <span style={{fontWeight:800,fontSize:15,color:C.text,letterSpacing:"-0.01em"}}>{isEN?"AI Analyst Report":"Informe de Analistas IA"}</span>
            </div>
            <span style={{fontSize:10,fontWeight:800,color:"#1A56DB",background:"rgba(26,86,219,0.1)",border:"1px solid rgba(26,86,219,0.25)",borderRadius:999,padding:"3px 10px",letterSpacing:0.4}}>✦ PREMIUM</span>
          </div>

          <div style={{position:"relative"}}>
          {/* Consenso */}
          <div style={{display:"flex",alignItems:"center",gap:14,marginBottom:14,flexWrap:"wrap"}}>
            <div>
              <div style={{fontSize:10.5,color:C.muted,fontWeight:700,letterSpacing:0.5,textTransform:"uppercase",marginBottom:3}}>{isEN?"Wall St. consensus":"Consenso Wall St."}</div>
              <div style={{fontSize:24,fontWeight:900,color:rColor,letterSpacing:"-0.02em",lineHeight:1}}>{rating}</div>
              <div style={{fontSize:11,color:C.muted,marginTop:3}}>{isEN?`Based on ${nAn} analysts`:`Basado en ${nAn} analistas`}</div>
            </div>
            {upside!=null && <div style={{marginLeft:"auto",textAlign:"right"}}>
              <div style={{fontSize:10.5,color:C.muted,fontWeight:700,letterSpacing:0.5,textTransform:"uppercase",marginBottom:3}}>{isEN?"Avg. target":"Objetivo medio"}</div>
              <div style={{fontSize:20,fontWeight:900,color:C.text,fontFamily:"monospace"}}>${target>=1000?target.toLocaleString("en",{maximumFractionDigits:0}):target.toFixed(2)}</div>
              <div style={{fontSize:12,fontWeight:800,color:upside>=0?"#16A34A":"#DC2626"}}>{upside>=0?"▲ +":"▼ "}{upside}% {isEN?"upside":"potencial"}</div>
            </div>}
          </div>
          {/* Medidor consenso */}
          <div style={{height:8,borderRadius:20,background:"linear-gradient(90deg,#DC2626,#F59E0B,#16A34A)",position:"relative",marginBottom:16}}>
            <div style={{position:"absolute",top:-4,left:`calc(${bull}% - 8px)`,width:16,height:16,borderRadius:"50%",background:"#fff",border:`3px solid ${rColor}`,boxShadow:"0 2px 6px rgba(0,0,0,0.2)"}}/>
          </div>
          {/* Desglose analistas */}
          <div style={{display:"grid",gridTemplateColumns:"1fr 1fr 1fr",gap:10,marginBottom:16}}>
            {[[isEN?"Buy":"Compra",buyN,"#16A34A"],[isEN?"Hold":"Mantener",holdN,"#F59E0B"],[isEN?"Sell":"Vender",sellN,"#DC2626"]].map(function(r,i){
              return <div key={i} style={{textAlign:"center",border:`1px solid ${C.border}`,borderRadius:11,padding:"9px 4px"}}>
                <div style={{fontSize:20,fontWeight:900,color:r[2]}}>{r[1]}</div>
                <div style={{fontSize:10.5,color:C.muted,fontWeight:700,marginTop:1}}>{r[0]}</div>
              </div>;
            })}
          </div>
          {/* Por qué — alcista vs riesgos */}
          <div style={{display:"grid",gridTemplateColumns:"1fr",gap:12}}>
            <div>
              <div style={{display:"flex",alignItems:"center",gap:6,marginBottom:7}}>{Pill(isEN?"WHY IT'S MOVING — BULL CASE":"POR QUÉ SUBE — TESIS ALCISTA","#16A34A")}</div>
              {bullF.map(function(b,i){return <div key={i} style={{display:"flex",gap:8,marginBottom:6,fontSize:13,lineHeight:1.5,color:C.text}}><span style={{color:"#16A34A",fontWeight:900,flexShrink:0}}>▲</span><span>{b}</span></div>;})}
            </div>
            <div>
              <div style={{display:"flex",alignItems:"center",gap:6,marginBottom:7,marginTop:4}}>{Pill(isEN?"KEY RISKS — BEAR CASE":"RIESGOS CLAVE — TESIS BAJISTA","#DC2626")}</div>
              {bearF.map(function(b,i){return <div key={i} style={{display:"flex",gap:8,marginBottom:6,fontSize:13,lineHeight:1.5,color:C.text}}><span style={{color:"#DC2626",fontWeight:900,flexShrink:0}}>▼</span><span>{b}</span></div>;})}
            </div>
          </div>
          <div style={{marginTop:12,fontSize:10.5,color:C.muted2,lineHeight:1.5}}>{isEN?"Compiled from analyst ratings, institutional flow and momentum. Educational — not financial advice.":"Recopilado de ratings de analistas, flujo institucional y momentum. Educativo — no es consejo financiero."}</div>

          {/* Gate para no-premium */}
          {!isPremium && <div style={{position:"absolute",inset:"56px 0 0 0",background:"linear-gradient(180deg,rgba(255,255,255,0) 0%, var(--c-surface) 42%)",backdropFilter:"blur(3px)",display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"flex-end",paddingBottom:8,borderRadius:14}}>
            <div style={{textAlign:"center",maxWidth:300}}>
              <div style={{fontSize:14,fontWeight:800,color:C.text,marginBottom:4}}>{isEN?"Unlock the full analyst report":"Desbloquea el informe completo"}</div>
              <div style={{fontSize:12,color:C.muted,marginBottom:12}}>{isEN?"Consensus, targets and the full why — on every stock.":"Consenso, objetivos y el porqué completo — en cada acción."}</div>
              <button onClick={()=>onNeedPremium?onNeedPremium():(onNeedAuth&&onNeedAuth())} style={{background:"linear-gradient(135deg,#1A56DB,#0B32B8)",color:"#fff",border:"none",borderRadius:11,padding:"11px 22px",fontSize:13.5,fontWeight:800,cursor:"pointer",fontFamily:"inherit",boxShadow:"0 8px 24px -8px rgba(26,86,219,0.6)"}}>✦ {isEN?"Try VIP free for 3 days →":"Prueba VIP 3 días gratis →"}</button>
            </div>
          </div>}
          </div>
        </div>
        );
      })()}

      {/* ── FUNDAMENTOS + NOTICIAS RECIENTES (Finnhub) ── */}
      {(function(){
        var isEN=lang==="en";
        var m=metric||{};
        var fmtCap=function(v){ if(!v) return "—"; if(v>=1e6) return "$"+(v/1e6).toFixed(2)+"T"; if(v>=1e3) return "$"+(v/1e3).toFixed(1)+"B"; return "$"+Number(v).toFixed(0)+"M"; };
        var pe=m.peTTM||m.peBasicExclExtraTTM;
        var divY=m.dividendYieldIndicatedAnnual!=null?m.dividendYieldIndicatedAnnual:m.currentDividendYieldTTM;
        var revG=m.revenueGrowthTTMYoy, epsG=m.epsGrowthTTMYoy, hi=m["52WeekHigh"], lo=m["52WeekLow"];
        var rows=[
          ["P/E (TTM)", pe!=null?Number(pe).toFixed(1):"—"],
          [isEN?"Dividend yield":"Rentab. dividendo", (divY!=null&&divY>0)?Number(divY).toFixed(2)+"%":(isEN?"No dividend":"No paga")],
          [isEN?"Revenue growth (YoY)":"Crec. ingresos (YoY)", revG!=null?((revG>=0?"+":"")+Number(revG).toFixed(1)+"%"):"—"],
          [isEN?"EPS growth (YoY)":"Crec. BPA (YoY)", epsG!=null?((epsG>=0?"+":"")+Number(epsG).toFixed(1)+"%"):"—"],
          [isEN?"Market cap":"Capitalización", fmtCap(m.marketCapitalization)],
          [isEN?"52-wk range":"Rango 52 sem", (lo&&hi)?("$"+Number(lo).toFixed(0)+" – $"+Number(hi).toFixed(0)):"—"],
        ];
        return (
        <div style={{marginBottom:20}}>
          <div style={{background:C.surface,border:`1px solid ${C.border}`,borderRadius:16,padding:"16px 18px",marginBottom:14}}>
            <div style={{fontWeight:800,fontSize:15,color:C.text,marginBottom:12,letterSpacing:"-0.01em"}}>{isEN?"Fundamentals":"Fundamentos"}</div>
            {!metric ? <div style={{fontSize:13,color:C.muted,padding:"6px 0"}}>{isEN?"Loading…":"Cargando…"}</div> :
            <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:"12px 18px"}}>
              {rows.map(function(r,i){return <div key={i} style={{display:"flex",justifyContent:"space-between",alignItems:"baseline",gap:8,borderBottom:`1px solid ${C.border}`,paddingBottom:8}}>
                <span style={{fontSize:12.5,color:C.muted}}>{r[0]}</span>
                <span style={{fontSize:13.5,fontWeight:800,color:C.text,fontFamily:"monospace"}}>{r[1]}</span>
              </div>;})}
            </div>}
          </div>
          <div style={{background:C.surface,border:`1px solid ${C.border}`,borderRadius:16,padding:"16px 18px"}}>
            <div style={{fontWeight:800,fontSize:15,color:C.text,marginBottom:12,letterSpacing:"-0.01em"}}>{isEN?"Recent news":"Noticias recientes"}</div>
            {!cnews ? <div style={{fontSize:13,color:C.muted,padding:"6px 0"}}>{isEN?"Loading…":"Cargando…"}</div> :
             cnews.length===0 ? <div style={{fontSize:13,color:C.muted,padding:"6px 0"}}>{isEN?"No recent news.":"Sin noticias recientes."}</div> :
             cnews.map(function(n,i){
               var dt=n.datetime?new Date(n.datetime*1000):null;
               return <a key={i} href={n.url} target="_blank" rel="noopener noreferrer" style={{display:"flex",gap:12,padding:"11px 0",borderBottom:i<cnews.length-1?`1px solid ${C.border}`:"none",textDecoration:"none"}}>
                 {n.image && <img src={n.image} alt="" loading="lazy" style={{width:56,height:56,borderRadius:10,objectFit:"cover",flexShrink:0,background:C.card2}} onError={e=>{e.target.style.display="none";}}/>}
                 <div style={{flex:1,minWidth:0}}>
                   <div style={{fontSize:13.5,fontWeight:600,color:C.text,lineHeight:1.4,display:"-webkit-box",WebkitLineClamp:2,WebkitBoxOrient:"vertical",overflow:"hidden"}}>{n.headline}</div>
                   <div style={{fontSize:11,color:C.muted2,marginTop:4}}>{n.source}{dt?" · "+dt.toLocaleDateString(isEN?"en-US":"es-ES",{month:"short",day:"numeric"}):""}</div>
                 </div>
               </a>;
             })}
          </div>
        </div>
        );
      })()}

      {/* Sentimiento Histórico — Premium */}
      <SentimentHistoryPremium
        ticker={ticker}
        lang={lang}
        isPremium={isPremium}
        onNeedPremium={onNeedPremium||onNeedAuth}
      />

      {/* Posts de la comunidad */}
      <div style={{display:"flex",alignItems:"center",gap:10,marginBottom:12}}>
        <h3 style={{margin:0,color:C.text,fontWeight:800,fontSize:16}}>
          💬 {lang==="en"?"Community posts about":"Posts de la comunidad sobre"} ${ticker}
        </h3>
        <span style={{background:C.accentDim,color:C.accentText,borderRadius:20,padding:"3px 10px",fontSize:11,fontWeight:700}}>{tkPosts.length}</span>
      </div>
      {tkPosts.length===0?(
        <div style={{textAlign:"center",padding:"28px 0",color:C.muted,background:C.surface,border:`1px solid ${C.border}`,borderRadius:14}}>
          <div style={{fontSize:28,marginBottom:8}}>📭</div>
          <div style={{fontSize:14}}>{lang==="en"?`Be the first to post about $${ticker}!`:`¡Sé el primero en comentar $${ticker}!`}</div>
        </div>
      ):(
        tkPosts.map(p=><PostCard key={p.id} post={p} onProfile={()=>{}} onPoints={()=>{}} onTickerClick={()=>{}} lang={lang} onRepost={onRepost} user={user} onNeedAuth={onNeedAuth} isPremium={isPremium} onNeedPremium={onNeedPremium||onNeedAuth}/>)
      )}

    </div>
  );
}

// ── TOPS / NOTICIAS / EARNINGS / TRENDING ─────────────────────────────────────
const thS={padding:"9px 14px",color:C.muted,fontWeight:700,fontSize:11,letterSpacing:0.8,textAlign:"left",background:C.card2};
const tdS={padding:"11px 14px",fontSize:13};
const TOP_D={activas:[{ticker:"NVDA",name:"NVIDIA",price:875.40,change:+2.8,vol:"$42.1B",mentions:1240},{ticker:"BTC",name:"Bitcoin",price:68420,change:+4.2,vol:"$38.6B",mentions:1100},{ticker:"TSLA",name:"Tesla",price:172.80,change:-3.1,vol:"$31.6B",mentions:980},{ticker:"AAPL",name:"Apple",price:189.50,change:+0.4,vol:"$28.3B",mentions:760},{ticker:"SPY",name:"S&P 500",price:521.30,change:-0.8,vol:"$22.4B",mentions:640}],ganadoras:[{ticker:"SMCI",name:"SuperMicro",price:950.20,change:+18.4,vol:"$8.2B"},{ticker:"ARM",name:"ARM Hold.",price:142.60,change:+11.2,vol:"$5.1B"},{ticker:"MSTR",name:"MicroStrat.",price:1820,change:+9.8,vol:"$4.7B"},{ticker:"COIN",name:"Coinbase",price:248.90,change:+7.3,vol:"$3.9B"},{ticker:"PLTR",name:"Palantir",price:24.80,change:+6.1,vol:"$2.8B"}],perdedoras:[{ticker:"BABA",name:"Alibaba",price:74.20,change:-8.9,vol:"$6.3B"},{ticker:"BYND",name:"Beyond Meat",price:7.40,change:-7.4,vol:"$0.8B"},{ticker:"RIVN",name:"Rivian",price:11.20,change:-6.2,vol:"$3.2B"},{ticker:"SNAP",name:"Snap",price:11.80,change:-5.8,vol:"$2.1B"},{ticker:"PYPL",name:"PayPal",price:61.40,change:-4.9,vol:"$4.5B"}]};

function TopTable({title,icon,data,cols}){
  return(
    <div style={{background:C.surface,border:`1px solid ${C.border}`,borderRadius:16,overflow:"hidden",marginBottom:18,boxShadow:C.shadow}}>
      <div style={{padding:"14px 18px",background:C.card2,borderBottom:`1px solid ${C.border}`,display:"flex",alignItems:"center",gap:8}}>
        <span style={{fontSize:18}}>{icon}</span><h3 style={{margin:0,color:C.text,fontSize:14,fontWeight:800}}>{title}</h3>
      </div>
      <div style={{overflowX:"auto"}}>
        <table style={{width:"100%",borderCollapse:"collapse"}}>
          <thead><tr><th style={thS}>#</th>{cols.map(c=><th key={c.k} style={thS}>{c.label}</th>)}</tr></thead>
          <tbody>{data.map((row,i)=>(
            <tr key={row.ticker} style={{borderBottom:`1px solid ${C.border}`,transition:"background 0.1s"}}
              onMouseEnter={e=>e.currentTarget.style.background=C.card2}
              onMouseLeave={e=>e.currentTarget.style.background="transparent"}>
              <td style={{...tdS,color:i<3?C.gold:"#94a3b8",fontWeight:800,fontSize:15}}>{i===0?"🥇":i===1?"🥈":i===2?"🥉":i+1}</td>
              {cols.map(c=>{const val=c.render?c.render(row):row[c.k],col=c.col?c.col(row):C.text;return <td key={c.k} style={{...tdS,color:col,fontFamily:c.mono?"monospace":"inherit",fontWeight:c.bold?700:500}}>{val}</td>;})}
            </tr>
          ))}</tbody>
        </table>
      </div>
    </div>
  );
}

const TOPS_TICKERS=[
  {ticker:"NVDA",name:"NVIDIA"},{ticker:"AAPL",name:"Apple"},{ticker:"TSLA",name:"Tesla"},
  {ticker:"AMZN",name:"Amazon"},{ticker:"META",name:"Meta"},{ticker:"MSFT",name:"Microsoft"},
  {ticker:"GOOGL",name:"Alphabet"},{ticker:"NFLX",name:"Netflix"},{ticker:"AMD",name:"AMD"},
  {ticker:"COIN",name:"Coinbase"},{ticker:"PLTR",name:"Palantir"},{ticker:"SMCI",name:"SuperMicro"},
  {ticker:"MSTR",name:"MicroStrategy"},{ticker:"ARM",name:"ARM Holdings"},{ticker:"BABA",name:"Alibaba"},
  {ticker:"RIVN",name:"Rivian"},{ticker:"SNAP",name:"Snap"},{ticker:"PYPL",name:"PayPal"},
  {ticker:"SPY",name:"S&P 500 ETF"},{ticker:"QQQ",name:"Nasdaq ETF"},
];

function TopsPage({posts=[],lang="es"}){
  const [tab,setTab]=useState("activas");
  const [quotes,setQuotes]=useState([]);
  const [loading,setLoading]=useState(true);
  const [marketClosed,setMarketClosed]=useState(false);
  const tabs=[["activas","Most Active"],["ganadoras","Top Gainers"],["perdedoras","Top Losers"]];

  const fetchData=()=>{
    setLoading(true);
    Promise.all(
      TOPS_TICKERS.map(({ticker,name})=>
        fetch(`https://finnhub.io/api/v1/quote?symbol=${ticker}&token=${FINNHUB_KEY}`)
          .then(r=>r.json())
          .then(q=>({ticker,name,price:q.c,change:q.dp,changeAbs:q.d,high:q.h,low:q.l,open:q.o,prevClose:q.pc}))
          .catch(()=>null)
      )
    ).then(results=>{
      const valid=results.filter(r=>r&&r.price>0);
      // Detect market closed: all changes are 0 or null
      const allZero=valid.length>0&&valid.every(q=>!q.change||q.change===0);
      setMarketClosed(allZero);
      if(allZero){
        // Calculate synthetic change from prevClose vs price
        const withChange=valid.map(q=>({
          ...q,
          change:q.prevClose&&q.price?+((q.price-q.prevClose)/q.prevClose*100).toFixed(2):0,
          changeAbs:q.prevClose&&q.price?+(q.price-q.prevClose).toFixed(2):0,
        }));
        setQuotes(withChange);
      } else {
        setQuotes(valid);
      }
      setLoading(false);
    }).catch(()=>setLoading(false));
  };

  useEffect(()=>{ fetchData(); },[]);

  const sorted=[...quotes].sort((a,b)=>Math.abs(b.change)-Math.abs(a.change));
  const ganadoras=[...quotes].filter(q=>q.change>0).sort((a,b)=>b.change-a.change).slice(0,5);
  const perdedoras=[...quotes].filter(q=>q.change<0).sort((a,b)=>a.change-b.change).slice(0,5);
  const activas=sorted.slice(0,5);

  const Row=({q,rank})=>(
    <div style={{display:"flex",alignItems:"center",gap:10,background:C.surface,border:`1px solid ${C.border}`,borderRadius:12,padding:"12px 16px",marginBottom:8,transition:"all 0.15s"}}
      onMouseEnter={e=>{e.currentTarget.style.borderColor=C.borderHover;e.currentTarget.style.boxShadow=C.shadow;}}
      onMouseLeave={e=>{e.currentTarget.style.borderColor=C.border;e.currentTarget.style.boxShadow="none";}}>
      <span style={{fontSize:12,fontWeight:800,color:C.muted2,width:18,textAlign:"center"}}>{rank}</span>
      <div style={{background:q.change>=0?C.bullBg:C.bearBg,borderRadius:8,padding:"6px 10px",minWidth:64,textAlign:"center"}}>
        <div style={{fontWeight:800,fontSize:13,fontFamily:"monospace",color:q.change>=0?C.bull:C.bear}}>{q.ticker}</div>
      </div>
      <div style={{flex:1,minWidth:0}}>
        <div style={{fontWeight:600,fontSize:13,color:C.text,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{q.name}</div>
        <div style={{fontSize:11,color:C.muted,fontFamily:"monospace"}}>${q.price?.toFixed(2)}</div>
      </div>
      <div style={{textAlign:"right",flexShrink:0}}>
        <div style={{fontWeight:800,fontSize:14,fontFamily:"monospace",color:q.change>=0?C.bull:C.bear}}>
          {q.change>=0?"+":""}{q.change?.toFixed(2)}%
        </div>
        <div style={{fontSize:11,color:C.muted,fontFamily:"monospace"}}>{q.change>=0?"+":""}{q.changeAbs?.toFixed(2)}</div>
      </div>
    </div>
  );

  return(
    <div>
      <div style={{display:"flex",alignItems:"center",gap:10,marginBottom:16,flexWrap:"wrap"}}>
        <h2 style={{margin:0,color:C.text,fontSize:18,fontWeight:800,display:"flex",alignItems:"center",gap:9}}>
          <span style={{width:30,height:30,borderRadius:9,background:"rgba(21,101,192,.1)",display:"inline-flex",alignItems:"center",justifyContent:"center",color:"#1565C0"}}><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.3" strokeLinecap="round" strokeLinejoin="round"><line x1="6" y1="20" x2="6" y2="13"/><line x1="12" y1="20" x2="12" y2="6"/><line x1="18" y1="20" x2="18" y2="10"/></svg></span>
          Market Tops
        </h2>
        {loading
          ?<span style={{fontSize:11,color:C.muted}}>Loading prices…</span>
          :marketClosed
            ?<span style={{fontSize:11,color:C.gold,fontWeight:700,display:"inline-flex",alignItems:"center",gap:5}}><span style={{width:6,height:6,borderRadius:"50%",background:C.gold}}/>Markets closed · Last close</span>
            :<span style={{fontSize:11,color:C.bull,fontWeight:700,display:"inline-flex",alignItems:"center",gap:5}}><span style={{width:6,height:6,borderRadius:"50%",background:C.bull,boxShadow:`0 0 5px ${C.bull}`}}/>Live · Finnhub</span>}
        <button onClick={fetchData}
          style={{marginLeft:"auto",background:"transparent",border:`1px solid ${C.border}`,borderRadius:8,padding:"5px 11px",cursor:"pointer",fontSize:11,color:C.muted,fontWeight:600,display:"inline-flex",alignItems:"center",gap:5}}
          title="Actualizar"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round"><polyline points="23 4 23 10 17 10"/><path d="M20.49 15a9 9 0 1 1-2.12-9.36L23 10"/></svg>Refresh</button>
      </div>
      <div style={{display:"flex",gap:6,marginBottom:20}}>
        {tabs.map(([k,l])=><button key={k} onClick={()=>setTab(k)} style={{background:tab===k?C.accent:"transparent",border:`1.5px solid ${tab===k?C.accent:C.border}`,borderRadius:10,padding:"7px 14px",cursor:"pointer",color:tab===k?"#fff":C.muted,fontSize:12,fontWeight:700,whiteSpace:"nowrap",transition:"all 0.15s"}}>{l}</button>)}
      </div>
      {loading?(
        <div style={{textAlign:"center",padding:"40px 0",color:C.muted}}>
          <div style={{fontSize:28,marginBottom:8}}>⏳</div>
          <div>Loading live data...</div>
        </div>
      ):(
        <>
          {tab==="activas"&&(activas.length>0?activas.map((q,i)=><Row key={q.ticker} q={q} rank={i+1}/>):<div style={{color:C.muted,textAlign:"center",padding:32}}>No data available</div>)}
          {tab==="ganadoras"&&(ganadoras.length>0?ganadoras.map((q,i)=><Row key={q.ticker} q={q} rank={i+1}/>):<div style={{color:C.muted,textAlign:"center",padding:32,fontSize:13}}>No gainers detected — market may be closed or prices unchanged</div>)}
          {tab==="perdedoras"&&(perdedoras.length>0?perdedoras.map((q,i)=><Row key={q.ticker} q={q} rank={i+1}/>):<div style={{color:C.muted,textAlign:"center",padding:32,fontSize:13}}>No losers detected — market may be closed or prices unchanged</div>)}
          {tab==="leaderboard"&&(()=>{
            // Calcular top traders esta semana por posts
            const weekAgo=Date.now()-7*24*60*60*1000;
            const map={};
            posts.forEach(p=>{
              if(!p.user)return;
              if(!map[p.user]) map[p.user]={user:p.user,avatar:p.avatar||"🦅",color:p.avatarColor||C.accent,posts:0,bull:0,bear:0,pts:0};
              map[p.user].posts++;
              map[p.user].pts+=10;
              if(p.sentiment==="bull") map[p.user].bull++; else map[p.user].bear++;
              if(p.likes) map[p.user].pts+=p.likes*5;
            });
            const lb=Object.values(map).sort((a,b)=>b.pts-a.pts).slice(0,5);
            const rankBg=i=>i===0?"linear-gradient(135deg,#FFD86B,#F0B429)":i===1?"linear-gradient(135deg,#E2E8F0,#94A3B8)":i===2?"linear-gradient(135deg,#E8A87C,#B45309)":"transparent";
            if(lb.length===0) return <div style={{textAlign:"center",padding:40,color:C.muted}}>
              <div style={{width:56,height:56,borderRadius:16,margin:"0 auto 12px",background:"rgba(21,101,192,.1)",display:"flex",alignItems:"center",justifyContent:"center",color:"#1565C0"}}><svg width="26" height="26" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M6 9H4.5a2.5 2.5 0 0 1 0-5H6"/><path d="M18 9h1.5a2.5 2.5 0 0 0 0-5H18"/><path d="M4 22h16"/><path d="M10 14.66V17c0 .55-.47.98-.97 1.21C7.85 18.75 7 20.24 7 22"/><path d="M14 14.66V17c0 .55.47.98.97 1.21C16.15 18.75 17 20.24 17 22"/><path d="M18 2H6v7a6 6 0 0 0 12 0V2z"/></svg></div>
              <div>{lang==="en"?"Post your first analysis to show up here!":"¡Publica tu primer análisis para aparecer aquí!"}</div>
            </div>;
            return lb.map((u,i)=>{
              const lvl=getLevel(u.pts);
              const bullPct=u.bull+u.bear>0?Math.round(u.bull/(u.bull+u.bear)*100):50;
              return(
                <div key={u.user} style={{background:i===0?`linear-gradient(135deg,rgba(15,94,104,0.06),rgba(245,158,11,0.03))`:C.surface,border:`1px solid ${i===0?"rgba(15,94,104,0.25)":C.border}`,borderRadius:14,padding:"14px 16px",marginBottom:8,display:"flex",alignItems:"center",gap:12,transition:"all 0.15s"}}
                  onMouseEnter={e=>{e.currentTarget.style.borderColor=C.borderHover;e.currentTarget.style.boxShadow=C.shadow;}}
                  onMouseLeave={e=>{e.currentTarget.style.borderColor=i===0?"rgba(15,94,104,0.25)":C.border;e.currentTarget.style.boxShadow="none";}}>
                  <span style={{width:26,height:26,borderRadius:"50%",flexShrink:0,display:"flex",alignItems:"center",justifyContent:"center",fontWeight:900,fontSize:12,color:i<3?"#2a1e00":C.muted2,background:rankBg(i),border:i<3?"none":`1px solid ${C.border}`}}>{i+1}</span>
                  <InitialsAvatar name={u.user} color={u.color} size={38}/>
                  <div style={{flex:1,minWidth:0}}>
                    <div style={{display:"flex",alignItems:"center",gap:6,marginBottom:3}}>
                      <span style={{fontWeight:800,fontSize:14,color:C.text}}>{u.user}</span>
                      <span style={{background:lvl.color+"20",color:lvl.color,borderRadius:6,padding:"1px 7px",fontSize:10,fontWeight:800,border:`1px solid ${lvl.color}44`}}>{lvl.icon} {lvl.label}</span>
                    </div>
                    <div style={{display:"flex",gap:10,alignItems:"center"}}>
                      <span style={{fontSize:11,color:C.muted}}>📝 {u.posts} posts</span>
                      <span style={{fontSize:11,color:C.bull}}>▲{u.bull}</span>
                      <span style={{fontSize:11,color:C.bear}}>▼{u.bear}</span>
                    </div>
                  </div>
                  <div style={{textAlign:"right",flexShrink:0}}>
                    <div style={{fontWeight:800,fontSize:15,color:i===0?C.gold:C.accent}}>{u.pts.toLocaleString()}</div>
                    <div style={{fontSize:10,color:C.muted}}>puntos</div>
                  </div>
                </div>
              );
            });
          })()}
        </>
      )}
    </div>
  );
}

function NoticiasPage({lang}){
  const isEN=lang==="en";
  const [cat,setCat]=useState("general");
  const [news,setNews]=useState([]);
  const [loading,setLoading]=useState(true);
  const [lastUp,setLastUp]=useState(null);
  const [spinning,setSpinning]=useState(false);

  const fetchNews=(c=cat)=>{
    setLoading(true);setSpinning(true);
    fetch(`https://finnhub.io/api/v1/news?category=${c}&token=${FINNHUB_KEY}`)
      .then(r=>r.json())
      .then(data=>{
        if(Array.isArray(data)){
          setNews(data.filter(n=>n.headline&&n.source).slice(0,30));
          setLastUp(new Date().toLocaleTimeString("en-US",{hour:"2-digit",minute:"2-digit"}));
        }
      })
      .catch(()=>{})
      .finally(()=>{setLoading(false);setTimeout(()=>setSpinning(false),600);});
  };

  useEffect(()=>{ fetchNews(cat); },[cat]);

  const cats=[
    {k:"general", l:isEN?"📰 Macro":"📰 Macro",     color:"#1565C0"},
    {k:"crypto",  l:"₿ Crypto",                      color:"#F59E0B"},
    {k:"forex",   l:"💱 Forex",                      color:"#16A34A"},
    {k:"merger",  l:"🏦 M&A",                        color:"#7C3AED"},
  ];

  const catColor = cats.find(c=>c.k===cat)?.color||"#1565C0";

  const timeAgo=(ts)=>{
    const diff=Math.floor((Date.now()/1000)-ts);
    if(diff<60) return isEN?`${diff}s ago`:`hace ${diff}s`;
    if(diff<3600) return isEN?`${Math.floor(diff/60)}m ago`:`hace ${Math.floor(diff/60)}m`;
    if(diff<86400) return isEN?`${Math.floor(diff/3600)}h ago`:`hace ${Math.floor(diff/3600)}h`;
    return isEN?`${Math.floor(diff/86400)}d ago`:`hace ${Math.floor(diff/86400)}d`;
  };

  // Derive simple sentiment from headline keywords
  const getSentiment=(h="")=>{
    const pos=/(record|surge|rally|gain|rise|profit|beat|bull|strong|growth|up|high|boost|soar)/i;
    const neg=/(fall|drop|crash|loss|decline|bear|weak|cut|miss|down|low|risk|fear|sell|warning)/i;
    if(pos.test(h)) return {label:isEN?"POSITIVE SENTIMENT":"SENTIMIENTO POSITIVO", color:"#16A34A", bg:"rgba(22,163,74,0.12)"};
    if(neg.test(h)) return {label:isEN?"NEGATIVE SENTIMENT":"SENTIMIENTO NEGATIVO", color:"#DC2626", bg:"rgba(220,38,38,0.10)"};
    return {label:isEN?"NEUTRAL":"NEUTRAL",                                           color:"#64748B", bg:"rgba(100,116,139,0.10)"};
  };

  // Extract unique tickers from news
  const topTickers = useMemo(()=>{
    const map={};
    news.forEach(n=>{
      if(n.related) n.related.split(",").forEach(t=>{
        const tk=t.trim().toUpperCase();
        if(tk&&tk.length<=5&&/^[A-Z]+$/.test(tk)){ map[tk]=(map[tk]||0)+1; }
      });
    });
    return Object.entries(map).sort((a,b)=>b[1]-a[1]).slice(0,6).map(e=>e[0]);
  },[news]);

  // Build AI summary from top tickers & first headlines
  const aiSummary = useMemo(()=>{
    if(news.length===0) return null;
    const tks = topTickers.slice(0,4);
    const first = news[0];
    const sentType = getSentiment(first?.headline||"");
    const tickerStr = tks.map(t=>`$${t}`).join(", ");
    if(cat==="crypto") return isEN
      ? `Crypto markets showing volatility. Institutional flows remain mixed. Watch ${tickerStr} for directional cues.`
      : `Los mercados cripto muestran volatilidad. El flujo institucional sigue mixto. Atentos a ${tickerStr}.`;
    if(cat==="forex") return isEN
      ? `Currency markets reacting to macro data. Key pairs under pressure. Monitor ${tickerStr||"DXY, EUR/USD"}.`
      : `Mercados de divisas reaccionando a datos macro. Pares clave bajo presión. Monitorear ${tickerStr||"DXY, EUR/USD"}.`;
    if(cat==="merger") return isEN
      ? `M&A activity picks up. ${tks[0]?`$${tks[0]} in focus.`:""} Premiums remain elevated in tech.`
      : `La actividad de M&A se acelera. ${tks[0]?`$${tks[0]} en foco.`:""} Primas elevadas en tech.`;
    return isEN
      ? `${sentType.label==="POSITIVE SENTIMENT"?"Markets in risk-on mode.":"Caution ahead."} ${tickerStr?`Key names: ${tickerStr}.`:""} Earnings and macro data driving price action today.`
      : `${sentType.label==="SENTIMIENTO POSITIVO"?"Mercado en modo risk-on.":"Cautela en el mercado."} ${tickerStr?`Nombres clave: ${tickerStr}.`:""} Earnings y datos macro mueven precios hoy.`;
  },[news,cat,topTickers,isEN]);

  const hero   = news[0]||null;
  const topRead= news.slice(1,6);
  const rest   = news.slice(1);

  return(
    <div>
      {/* ── PAGE HEADER ── */}
      <div style={{marginBottom:16}}>
        <div style={{display:"flex",alignItems:"center",gap:10,flexWrap:"wrap"}}>
          <div>
            <div style={{fontSize:11,fontWeight:700,color:catColor,letterSpacing:2,textTransform:"uppercase",marginBottom:3}}>/// {isEN?"NEWS":"NOTICIAS"}</div>
            <h2 style={{margin:0,color:C.text,fontSize:22,fontWeight:900,letterSpacing:"-0.5px"}}>{isEN?"Market News":"Noticias del Mercado"}</h2>
            <p style={{margin:"4px 0 0",color:C.muted,fontSize:13}}>{isEN?"What matters, with sentiment and affected tickers — no noise.":"Lo importante, con el sentimiento y los tickers afectados — sin ruido."}</p>
          </div>
          <div style={{marginLeft:"auto",display:"flex",alignItems:"center",gap:8,flexShrink:0}}>
            {lastUp
              ? <span style={{display:"flex",alignItems:"center",gap:5,background:"rgba(34,197,94,0.1)",color:"#16a34a",border:"1px solid rgba(34,197,94,0.3)",borderRadius:20,padding:"4px 12px",fontSize:11,fontWeight:700}}>
                  <span style={{width:6,height:6,borderRadius:"50%",background:"#22c55e",display:"inline-block",animation:"nexo-pulse 1.5s infinite"}}/>LIVE
                </span>
              : <span style={{display:"flex",alignItems:"center",gap:5,background:"rgba(148,163,184,0.1)",color:"#64748b",border:"1px solid rgba(148,163,184,0.2)",borderRadius:20,padding:"4px 12px",fontSize:11,fontWeight:700}}>
                  <span style={{width:6,height:6,borderRadius:"50%",background:"#64748b",display:"inline-block"}}/>{loading?"Loading":"Finnhub"}
                </span>
            }
            <span style={{color:C.muted2,fontSize:11}}>{lastUp?`${isEN?"Updated":"Actualizado"} ${lastUp}`:""}</span>
            <button onClick={()=>fetchNews(cat)} disabled={loading}
              style={{display:"flex",alignItems:"center",gap:5,background:"var(--c-card2)",border:"1px solid var(--c-border)",borderRadius:20,padding:"6px 14px",cursor:loading?"not-allowed":"pointer",color:C.muted,fontSize:12,fontWeight:700,transition:"all 0.2s",fontFamily:"inherit"}}>
              <span style={{display:"inline-block",transition:"transform 0.6s",transform:spinning?"rotate(360deg)":"rotate(0deg)"}}>⟳</span>
              {loading?(isEN?"Loading...":"Cargando..."):(isEN?"Refresh":"Actualizar")}
            </button>
          </div>
        </div>

        {/* Category tabs */}
        <div style={{display:"flex",gap:6,marginTop:14,flexWrap:"wrap"}}>
          {cats.map(c=>(
            <button key={c.k} onClick={()=>setCat(c.k)}
              style={{background:cat===c.k?c.color:"var(--c-surface)",border:`1.5px solid ${cat===c.k?c.color:"var(--c-border)"}`,borderRadius:24,padding:"7px 18px",cursor:"pointer",color:cat===c.k?"#fff":C.muted,fontSize:13,fontWeight:700,transition:"all 0.15s",fontFamily:"inherit",boxShadow:cat===c.k?`0 2px 10px ${c.color}44`:"none"}}>
              {c.l}
            </button>
          ))}
        </div>
      </div>

      {/* ── LOADING / EMPTY ── */}
      {loading?(
        <div style={{textAlign:"center",padding:"60px 0",color:C.muted}}>
          <div style={{width:36,height:36,borderRadius:"50%",border:`3px solid rgba(21,101,192,0.2)`,borderTopColor:catColor,animation:"spin 1s linear infinite",margin:"0 auto 12px"}}/>
          <div style={{fontSize:14}}>{isEN?"Loading news...":"Cargando noticias..."}</div>
        </div>
      ):news.length===0?(
        <div style={{textAlign:"center",padding:"60px 0",color:C.muted}}>
          <div style={{fontSize:32,marginBottom:8}}>📭</div>
          <div style={{fontSize:14}}>{isEN?"No news at the moment":"No hay noticias en este momento"}</div>
        </div>
      ):(
        /* ── 2-COLUMN LAYOUT ── */
        <div className="nexo-news-grid" style={{display:"grid",gridTemplateColumns:"1fr 300px",gap:24,alignItems:"start"}}>

          {/* LEFT — Hero + news list */}
          <div>
            {/* HERO ARTICLE */}
            {hero&&(()=>{
              const sent=getSentiment(hero.headline);
              const tickers=(hero.related||"").split(",").map(t=>t.trim()).filter(t=>t&&t.length<=5&&/^[A-Z]+$/.test(t)).slice(0,4);
              return(
                <a href={hero.url} target="_blank" rel="noopener noreferrer"
                  style={{display:"block",textDecoration:"none",background:"var(--c-surface)",border:"1px solid var(--c-border)",borderRadius:18,marginBottom:20,overflow:"hidden",boxShadow:"var(--c-shadowMd)",transition:"transform 0.15s,box-shadow 0.15s"}}
                  onMouseEnter={e=>{e.currentTarget.style.transform="translateY(-2px)";e.currentTarget.style.boxShadow="0 8px 32px rgba(21,101,192,0.14)";}}
                  onMouseLeave={e=>{e.currentTarget.style.transform="";e.currentTarget.style.boxShadow="var(--c-shadowMd)";}}>
                  {/* Hero image */}
                  <div style={{position:"relative",height:220,background:`linear-gradient(135deg,#0A1633 0%,#0D2A5E 100%)`,overflow:"hidden"}}>
                    {hero.image&&<img src={hero.image} alt="" style={{width:"100%",height:"100%",objectFit:"cover",opacity:0.55}} onError={e=>{e.target.style.display="none";}}/>}
                    <div style={{position:"absolute",inset:0,background:"linear-gradient(to top, rgba(10,22,51,0.85) 0%, transparent 60%)"}}/>
                    {/* Sentiment badge */}
                    <div style={{position:"absolute",top:16,left:16,background:sent.bg,border:`1px solid ${sent.color}55`,borderRadius:20,padding:"5px 12px",display:"flex",alignItems:"center",gap:5}}>
                      <span style={{width:6,height:6,borderRadius:"50%",background:sent.color,display:"inline-block"}}/>
                      <span style={{fontSize:10,fontWeight:800,color:sent.color,letterSpacing:1,textTransform:"uppercase"}}>{sent.label}</span>
                    </div>
                  </div>
                  {/* Hero body */}
                  <div style={{padding:"18px 20px 20px"}}>
                    <div style={{display:"flex",alignItems:"center",gap:6,marginBottom:10,flexWrap:"wrap"}}>
                      <span style={{background:catColor,color:"#fff",borderRadius:6,padding:"2px 9px",fontSize:10.5,fontWeight:800}}>{hero.source}</span>
                      {tickers.map(t=>(
                        <span key={t} style={{background:"rgba(21,101,192,0.08)",color:"#1565C0",borderRadius:5,padding:"2px 7px",fontSize:10.5,fontWeight:700,fontFamily:"monospace"}}>${t}</span>
                      ))}
                      <span style={{color:C.muted2,fontSize:11,marginLeft:"auto"}}>{timeAgo(hero.datetime)}</span>
                    </div>
                    <h3 style={{margin:"0 0 8px",color:C.text,fontSize:17,fontWeight:800,lineHeight:1.4,letterSpacing:"-0.3px"}}>{hero.headline}</h3>
                    {hero.summary&&<p style={{margin:"0 0 14px",color:C.muted,fontSize:13,lineHeight:1.6,overflow:"hidden",display:"-webkit-box",WebkitLineClamp:2,WebkitBoxOrient:"vertical"}}>{hero.summary}</p>}
                    <span style={{display:"inline-flex",alignItems:"center",gap:5,background:"rgba(21,101,192,0.07)",color:"#1565C0",border:"1px solid rgba(21,101,192,0.2)",borderRadius:8,padding:"7px 14px",fontSize:12,fontWeight:700}}>
                      {isEN?"Read analysis →":"Leer análisis →"}
                    </span>
                  </div>
                </a>
              );
            })()}

            {/* REST OF NEWS */}
            {rest.map((n,i)=>{
              const sent=getSentiment(n.headline);
              const tickers=(n.related||"").split(",").map(t=>t.trim()).filter(t=>t&&t.length<=5&&/^[A-Z]+$/.test(t)).slice(0,3);
              return(
                <div key={i}>
                  {i>0 && i%5===0 && <><AdBannerFeed/><MediaNetBannerFeed/></>}
                  <a href={n.url} target="_blank" rel="noopener noreferrer"
                    style={{display:"block",textDecoration:"none",background:"var(--c-surface)",border:"1px solid var(--c-border)",borderRadius:14,padding:"14px 16px",marginBottom:10,boxShadow:"var(--c-shadow)",transition:"box-shadow 0.2s,transform 0.15s"}}
                    onMouseEnter={e=>{e.currentTarget.style.boxShadow="var(--c-shadowMd)";e.currentTarget.style.transform="translateY(-1px)";}}
                    onMouseLeave={e=>{e.currentTarget.style.boxShadow="var(--c-shadow)";e.currentTarget.style.transform="";}}>
                    <div style={{display:"flex",gap:12,alignItems:"flex-start"}}>
                      {n.image&&<img src={n.image} alt="" style={{width:76,height:56,objectFit:"cover",borderRadius:10,flexShrink:0,background:"#F1F5F9"}} onError={e=>{e.target.style.display="none";}}/>}
                      <div style={{flex:1,minWidth:0}}>
                        <div style={{display:"flex",alignItems:"center",gap:5,marginBottom:5,flexWrap:"wrap"}}>
                          <span style={{background:"rgba(21,101,192,0.08)",color:"#1565C0",borderRadius:5,padding:"2px 8px",fontSize:10.5,fontWeight:800}}>{n.source}</span>
                          {tickers.map(t=>(
                            <span key={t} style={{background:"rgba(0,0,0,0.04)",color:C.muted,borderRadius:4,padding:"2px 6px",fontSize:10,fontFamily:"monospace",fontWeight:700}}>${t}</span>
                          ))}
                          <span style={{display:"inline-flex",alignItems:"center",gap:3,background:sent.bg,borderRadius:4,padding:"2px 7px",fontSize:10,fontWeight:700,color:sent.color}}>
                            <span style={{width:5,height:5,borderRadius:"50%",background:sent.color,display:"inline-block"}}/>
                            {sent.label.split(" ")[0].charAt(0).toUpperCase()+sent.label.split(" ")[0].slice(1).toLowerCase()}
                          </span>
                          <span style={{color:C.muted2,fontSize:10.5,marginLeft:"auto"}}>{timeAgo(n.datetime)}</span>
                        </div>
                        <p style={{margin:0,color:C.text,fontSize:13.5,fontWeight:600,lineHeight:1.5,overflow:"hidden",display:"-webkit-box",WebkitLineClamp:2,WebkitBoxOrient:"vertical"}}>{n.headline}</p>
                        {n.summary&&<p style={{margin:"4px 0 0",color:C.muted,fontSize:12,lineHeight:1.5,overflow:"hidden",display:"-webkit-box",WebkitLineClamp:1,WebkitBoxOrient:"vertical"}}>{n.summary}</p>}
                      </div>
                    </div>
                  </a>
                </div>
              );
            })}
          </div>

          {/* RIGHT SIDEBAR */}
          <div className="nexo-news-sidebar" style={{display:"flex",flexDirection:"column",gap:14,position:"sticky",top:16}}>

            {/* Lo más leído */}
            <div style={{background:"var(--c-surface)",border:"1px solid var(--c-border)",borderRadius:16,padding:"16px 18px",boxShadow:"var(--c-shadow)"}}>
              <div style={{fontSize:10,fontWeight:800,color:catColor,letterSpacing:2,textTransform:"uppercase",marginBottom:12}}>
                {isEN?"TOP STORIES TODAY":"LO MÁS LEÍDO HOY"}
              </div>
              {topRead.map((n,i)=>(
                <a key={i} href={n.url} target="_blank" rel="noopener noreferrer"
                  style={{display:"flex",gap:12,alignItems:"flex-start",marginBottom:i<topRead.length-1?12:0,textDecoration:"none",padding:"8px 0",borderBottom:i<topRead.length-1?"1px solid var(--c-border)":"none"}}>
                  <span style={{fontWeight:800,color:catColor,fontSize:20,lineHeight:1,minWidth:24,flexShrink:0,opacity:0.8}}>0{i+1}</span>
                  <p style={{margin:0,color:C.text,fontSize:12.5,fontWeight:600,lineHeight:1.5,overflow:"hidden",display:"-webkit-box",WebkitLineClamp:2,WebkitBoxOrient:"vertical"}}>{n.headline}</p>
                </a>
              ))}
            </div>

            {/* Resumen IA */}
            <div style={{background:"var(--c-surface)",border:`1.5px solid ${catColor}33`,borderRadius:16,padding:"16px 18px",boxShadow:`0 2px 16px ${catColor}14`}}>
              <div style={{display:"flex",alignItems:"center",gap:6,marginBottom:10}}>
                <div style={{width:28,height:28,borderRadius:8,background:`linear-gradient(135deg,${catColor},${catColor}cc)`,display:"flex",alignItems:"center",justifyContent:"center",fontSize:14,flexShrink:0}}>🤖</div>
                <div>
                  <div style={{fontSize:10,fontWeight:800,color:catColor,letterSpacing:1.5,textTransform:"uppercase"}}>{isEN?"AI SUMMARY":"RESUMEN IA"}</div>
                  <div style={{fontSize:9.5,color:C.muted2}}>
                    {new Date().toLocaleTimeString("en-US",{hour:"2-digit",minute:"2-digit"})}
                  </div>
                </div>
              </div>
              {aiSummary?(
                <p style={{margin:"0 0 10px",color:C.text,fontSize:12.5,lineHeight:1.65}}>
                  {aiSummary.split(/(\$[A-Z]{1,5})/g).map((p,i)=>
                    /^\$[A-Z]{1,5}$/.test(p)
                      ? <strong key={i} style={{color:catColor}}>{p}</strong>
                      : p
                  )}
                </p>
              ):<p style={{margin:"0 0 10px",color:C.muted,fontSize:12.5,lineHeight:1.65}}>Loading summary...</p>}
              <div style={{display:"flex",gap:6,flexWrap:"wrap"}}>
                {topTickers.slice(0,5).map(t=>(
                  <span key={t} style={{background:`${catColor}11`,color:catColor,borderRadius:6,padding:"3px 8px",fontSize:11,fontWeight:700,fontFamily:"monospace"}}>${t}</span>
                ))}
              </div>
              <div style={{marginTop:10,fontSize:10,color:C.muted2,display:"flex",alignItems:"center",gap:4}}>
                🤖 {isEN?`Generated by NEXO AI · ${news.length} sources`:`Generado por NEXO IA · ${news.length} fuentes`}
              </div>
            </div>

            {/* Top tickers found in news */}
            {topTickers.length>0&&(
              <div style={{background:"var(--c-surface)",border:"1px solid var(--c-border)",borderRadius:16,padding:"14px 18px",boxShadow:"var(--c-shadow)"}}>
                <div style={{fontSize:10,fontWeight:800,color:C.muted,letterSpacing:2,textTransform:"uppercase",marginBottom:10}}>
                  {isEN?"TICKERS IN NEWS":"TICKERS EN NOTICIAS"}
                </div>
                <div style={{display:"flex",flexWrap:"wrap",gap:6}}>
                  {topTickers.map(t=>(
                    <span key={t} style={{background:"rgba(21,101,192,0.07)",color:"#1565C0",borderRadius:8,padding:"5px 10px",fontSize:12,fontWeight:800,fontFamily:"monospace",border:"1px solid rgba(21,101,192,0.15)"}}>${t}</span>
                  ))}
                </div>
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

