// Logos cripto (CDN público spothq). Cae a letra si no carga.
const CRYPTO_LOGO = {
  BTC:"btc", ETH:"eth", SOL:"sol", BNB:"bnb", XRP:"xrp", ADA:"ada",
  DOGE:"doge", AVAX:"avax", MATIC:"matic", LTC:"ltc", LINK:"link", DOT:"dot",
};
const logoUrlFor = (sym) => {
  const s=(sym||"").toUpperCase();
  // Tickers cuyo logo oficial confunde (parece el producto, no el ticker) → forzar monograma
  if(s==="GOOGL"||s==="GOOG") return null;
  if(CRYPTO_LOGO[s]) return `https://cdn.jsdelivr.net/gh/spothq/cryptocurrency-icons@master/128/color/${CRYPTO_LOGO[s]}.png`;
  // Logos de acciones por símbolo (repo nvstly en jsdelivr) — cubre miles de tickers; si no existe → letra
  if(/^[A-Z.]{1,6}$/.test(s)) return `https://cdn.jsdelivr.net/gh/nvstly/icons/ticker_icons/${s}.png`;
  return null;
};
// Badge con logo oficial; si no hay/falla → cuadrito de color con la inicial
function LogoBadge({sym, col="#0F4C81", size=38, radius=10}){
  const [err,setErr]=useState(false);
  const [loaded,setLoaded]=useState(false);
  const url=logoUrlFor(sym);
  const showLogo = url && !err;
  return(
    <div style={{position:"relative",width:size,height:size,borderRadius:radius,flexShrink:0,overflow:"hidden",
      background:(showLogo&&loaded)?"#fff":col,
      border:(showLogo&&loaded)?"1px solid #EEF2F7":"none",
      boxShadow:(showLogo&&loaded)?`0 2px 8px ${col}22`:`0 3px 10px ${col}55`,
      display:"flex",alignItems:"center",justifyContent:"center"}}>
      {/* Letra de color visible de inmediato (y como fallback) */}
      {!(showLogo&&loaded)&&<span style={{fontSize:Math.round(size*0.42),fontWeight:900,color:"#fff"}}>{(sym||"?").slice(0,1)}</span>}
      {/* Logo real encima cuando carga */}
      {showLogo&&(
        <img src={url} alt={sym} loading="lazy"
          onLoad={()=>setLoaded(true)} onError={()=>setErr(true)}
          style={{position:"absolute",inset:0,margin:"auto",width:"78%",height:"78%",objectFit:"contain",opacity:loaded?1:0,transition:"opacity 0.2s"}}/>
      )}
    </div>
  );
}

// Hook compartido para precios reales de CoinGecko
function useCryptoPrices(){
  const [cryptoPrices, setCryptoPrices] = useState({});
  const [lastUpdate, setLastUpdate] = useState(null);

  const fetchPrices = useCallback(()=>{
    fetch(`https://api.coingecko.com/api/v3/simple/price?ids=${COINGECKO_IDS}&vs_currencies=usd&include_24hr_change=true`)
      .then(r=>r.ok?r.json():Promise.reject())
      .then(data=>{
        const mapped = {
          BTC:{ p:data.bitcoin?.usd||0,         c:+(data.bitcoin?.usd_24h_change||0).toFixed(2) },
          ETH:{ p:data.ethereum?.usd||0,         c:+(data.ethereum?.usd_24h_change||0).toFixed(2) },
          SOL:{ p:data.solana?.usd||0,           c:+(data.solana?.usd_24h_change||0).toFixed(2) },
          BNB:{ p:data.binancecoin?.usd||0,      c:+(data.binancecoin?.usd_24h_change||0).toFixed(2) },
        };
        setCryptoPrices(mapped);
        setLastUpdate(new Date());
      })
      .catch(()=>{}); // silencioso — mantiene datos anteriores
  },[]);

  useEffect(()=>{
    fetchPrices();
    const iv = setInterval(fetchPrices, 60000); // cada 60s (límite gratuito CoinGecko)
    return ()=>clearInterval(iv);
  },[fetchPrices]);

  return {cryptoPrices, lastUpdate};
}

function TickerStrip(){
  const lp = useContext(PriceCtx);
  const isLive = Object.keys(lp).length > 0;

  // Construir tickers con precio real del PriceCtx
  const tickers = TICKER_DATA_INIT.map(t=>{
    const live = lp[t.s];
    return { ...t, p: live?.price ?? t.p, c: live?.change ?? t.c };
  });

  const items = [...tickers, ...tickers];

  return(
    <div style={{background:"#060e1c",borderBottom:"1px solid rgba(255,255,255,0.07)",overflow:"hidden",height:34,position:"sticky",top:0,zIndex:300}}>
      <style>{`
        @keyframes tickerScroll { 0%{transform:translateX(0)} 100%{transform:translateX(-50%)} }
        .ticker-track { display:flex; gap:0; animation:tickerScroll 80s linear infinite; width:max-content; }
        .ticker-track:hover { animation-play-state:paused; }
      `}</style>
      {/* Indicador live */}
      <div style={{position:"absolute",right:0,top:0,bottom:0,zIndex:2,background:"linear-gradient(90deg,transparent,#060e1c 60%)",display:"flex",alignItems:"center",paddingRight:10,paddingLeft:30}}>
        {isLive
          ? <span style={{display:"flex",alignItems:"center",gap:4,fontSize:9,color:"#22c55e",fontWeight:700,whiteSpace:"nowrap"}}>
              <span style={{width:5,height:5,borderRadius:"50%",background:"#22c55e",display:"inline-block",animation:"nexo-pulse 1.5s infinite"}}/>LIVE
            </span>
          : <span style={{fontSize:9,color:"#334155"}}>~</span>
        }
      </div>
      <div className="ticker-track">
        {items.map((t,i)=>(
          <a key={i} href={`https://www.tradingview.com/symbols/${t.cg?t.s+"USD":t.s}/`}
            target="_blank" rel="noopener noreferrer"
            style={{display:"flex",alignItems:"center",gap:6,padding:"0 16px",height:34,textDecoration:"none",borderRight:"1px solid rgba(255,255,255,0.05)",flexShrink:0,whiteSpace:"nowrap"}}>
            <span style={{fontWeight:800,fontSize:11,color:t.col,letterSpacing:0.5}}>{t.s}</span>
            <span style={{fontFamily:"monospace",fontSize:11,color:"#e2e8f0",fontWeight:600}}>
              {t.p>0?t.p.toLocaleString("en-US",{minimumFractionDigits:t.p>100?1:2,maximumFractionDigits:t.p>100?1:2}):"—"}
            </span>
            <span style={{fontSize:10,fontWeight:700,color:t.c>=0?"#22c55e":"#ef4444"}}>{t.c>=0?"+":""}{t.c.toFixed(2)}%</span>
            {t.cg&&<span style={{fontSize:8,color:"#22c55e",opacity:0.7}}>●</span>}
          </a>
        ))}
      </div>
    </div>
  );
}

