function MoverSparkline({dir, chg}){
  const bull = chg >= 0;
  const color = bull ? "#22c55e" : "#ef4444";
  const W=88, H=36;
  const pts = bull
    ? [[0,30],[18,26],[36,20],[54,14],[72,8],[88,4]]
    : [[0,6],[18,10],[36,16],[54,22],[72,27],[88,32]];
  const pathD = pts.map((p,i)=>`${i===0?"M":"L"}${p[0]},${p[1]}`).join(" ");
  const fillD = `${pathD} L${W},${H} L0,${H} Z`;
  return(
    <svg width={W} height={H} viewBox={`0 0 ${W} ${H}`} style={{display:"block"}}>
      <defs>
        <linearGradient id={`mg_${dir}_${chg>0?"u":"d"}`} x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stopColor={color} stopOpacity="0.35"/>
          <stop offset="100%" stopColor={color} stopOpacity="0"/>
        </linearGradient>
      </defs>
      <path d={fillD} fill={`url(#mg_${dir}_${chg>0?"u":"d"})`}/>
      <path d={pathD} fill="none" stroke={color} strokeWidth="2" strokeLinejoin="round" strokeLinecap="round"/>
    </svg>
  );
}

function TrendingPage({posts=[],lang="es"}){
  const isEN=lang==="en";
  // Precios EN VIVO desde el sistema central (1 fuente cacheada compartida + WebSocket).
  // Esto da tiempo real SIN saturar la API: da igual cuántas acciones haya.
  const lp = useContext(PriceCtx);
  const registerPx = useContext(PriceRegisterCtx);
  const [refreshing,setRefreshing]=useState(false);
  const [lastUpdate,setLastUpdate]=useState(null);
  const [tick,setTick]=useState(0);
  const loading=false;

  // Registrar todos los tickers (grandes + emergentes) para que reciban precio en vivo
  useEffect(()=>{
    if(!registerPx) return;
    registerPx([...ALL_MOVERS_POOL,...EMERGING_POOL].map(m=>m.ticker));
  },[registerPx]);

  // Quotes derivados de PriceCtx (se actualizan solos cada ~1s en horario de mercado)
  const quotes={};
  [...ALL_MOVERS_POOL,...EMERGING_POOL].forEach(m=>{ const v=lp&&lp[m.ticker]; if(v&&v.price>0) quotes[m.ticker]={price:v.price,change:v.change}; });

  // Ranking por mayor movimiento — se re-calcula cada 10s (no en cada tick, para que no salte)
  const rankPool=(pool,n)=>[...pool].sort((a,b)=>Math.abs((quotes[b.ticker]?.change)??b.fallbackChg)-Math.abs((quotes[a.ticker]?.change)??a.fallbackChg)).slice(0,n);
  const topBig = useMemo(()=>rankPool(ALL_MOVERS_POOL,8),[tick,lang]);
  const topEmerging = useMemo(()=>rankPool(EMERGING_POOL,8),[tick,lang]);
  // Filas combinadas con cabeceras de sección
  const rows = [
    {_header:isEN?"Large Caps · biggest movers":"Grandes · mayores movimientos"},
    ...topBig.map((m,idx)=>({...m,_rank:idx})),
    {_header:isEN?"Emerging · most volatile":"Emergentes · más volátiles"},
    ...topEmerging.map((m,idx)=>({...m,_rank:idx})),
  ];

  const fetchQuotes=(isRefresh)=>{ setRefreshing(true); setTick(t=>t+1); setLastUpdate(new Date().toLocaleTimeString(isEN?"en-US":"es-ES",{hour:"2-digit",minute:"2-digit"})); setTimeout(()=>setRefreshing(false),500); };

  useEffect(()=>{
    setLastUpdate(new Date().toLocaleTimeString(isEN?"en-US":"es-ES",{hour:"2-digit",minute:"2-digit"}));
    const t=setInterval(()=>{ setTick(x=>x+1); setLastUpdate(new Date().toLocaleTimeString(isEN?"en-US":"es-ES",{hour:"2-digit",minute:"2-digit"})); },10000);
    return()=>clearInterval(t);
  },[]);

  const rankMedal=(i)=>{
    if(i===0) return <span style={{fontSize:22}}>🥇</span>;
    if(i===1) return <span style={{fontSize:22}}>🥈</span>;
    if(i===2) return <span style={{fontSize:22}}>🥉</span>;
    return <span style={{fontSize:14,fontWeight:900,color:C.muted2}}>{i+1}</span>;
  };

  return(
    <div>
      <style>{`@keyframes nexoGreenMove{0%{background-position:0% 50%}100%{background-position:200% 50%}}@keyframes nexoDotGlow{0%,100%{box-shadow:0 0 4px 1px rgba(34,197,94,.55);opacity:.75}50%{box-shadow:0 0 13px 4px rgba(34,197,94,.95);opacity:1}}`}</style>
      {/* 🌐 Resumen del mercado (índices + crypto + commodities) */}
      <MarketOverview lang={lang}/>
      {/* Termómetro NexoTrade */}
      <NexoTermometro lang={lang}/>

      {/* Header */}
      <div style={{display:"flex",alignItems:"center",gap:10,marginBottom:20,flexWrap:"wrap"}}>
        <h2 style={{margin:0,fontSize:18,fontWeight:900,display:"flex",alignItems:"center",gap:7}}>
          <span style={{fontSize:18}}>🔥</span>
          <span style={{background:"linear-gradient(90deg,#15803d,#22c55e,#86efac,#22c55e,#15803d)",backgroundSize:"200% auto",WebkitBackgroundClip:"text",backgroundClip:"text",WebkitTextFillColor:"transparent",color:"transparent",animation:"nexoGreenMove 3s linear infinite",filter:"drop-shadow(0 0 6px rgba(34,197,94,0.45))"}}>{isEN?"Trending on NexoTrade":"Trending en NexoTrade"}</span>
        </h2>
        <span style={{background:"rgba(239,68,68,0.12)",color:"#EF4444",borderRadius:20,padding:"3px 12px",fontSize:11,fontWeight:700,border:"1px solid rgba(239,68,68,0.25)"}}>
          ● {isEN?"LAST 24H":"ÚLTIMAS 24H"}
        </span>
        {/* Refresh button */}
        <button onClick={()=>fetchQuotes(true)} disabled={refreshing||loading}
          style={{display:"flex",alignItems:"center",gap:5,background:refreshing?"rgba(15,76,129,0.15)":"rgba(15,76,129,0.08)",border:"1px solid rgba(15,76,129,0.3)",borderRadius:20,padding:"4px 13px",fontSize:11,fontWeight:700,color:"#0F4C81",cursor:refreshing?"not-allowed":"pointer",transition:"all 0.2s"}}>
          <span style={{display:"inline-block",animation:refreshing?"spin 0.7s linear infinite":"none",fontSize:12}}>🔄</span>
          {refreshing?(isEN?"Refreshing…":"Actualizando…"):(isEN?"Refresh":"Refrescar")}
        </button>
        <span style={{marginLeft:"auto",fontSize:11,color:"#22c55e",fontWeight:700,display:"flex",alignItems:"center",gap:5}}>
          <span style={{width:7,height:7,borderRadius:"50%",background:"#22c55e",display:"inline-block",animation:"pulse 2s infinite"}}/>
          {loading&&!refreshing?"Loading…":`Live · ${lastUpdate||"--:--"}`}
        </span>
      </div>

      {/* Cards */}
      {rows.map((m,i)=>{
        if(m._header) return(
          <div key={"h"+i} style={{display:"flex",justifyContent:"center",margin:i===0?"6px 0 16px":"28px 0 16px"}}>
            <span style={{display:"inline-flex",alignItems:"center",gap:9,padding:"7px 20px",borderRadius:999,background:"linear-gradient(135deg,rgba(34,197,94,0.15),rgba(34,197,94,0.04))",border:"1px solid rgba(34,197,94,0.34)",boxShadow:"0 0 20px rgba(34,197,94,0.16)"}}>
              <span style={{width:8,height:8,borderRadius:"50%",background:"#22c55e",display:"inline-block",flexShrink:0,animation:"nexoDotGlow 1.6s ease-in-out infinite"}}/>
              <span style={{background:"linear-gradient(90deg,#15803d,#22c55e,#86efac,#22c55e,#15803d)",backgroundSize:"200% auto",WebkitBackgroundClip:"text",backgroundClip:"text",WebkitTextFillColor:"transparent",color:"transparent",animation:"nexoGreenMove 3s linear infinite",whiteSpace:"nowrap",fontSize:12.5,fontWeight:900,letterSpacing:1.3,textTransform:"uppercase"}}>{m._header}</span>
            </span>
          </div>
        );
        const q=quotes[m.ticker]||{};
        const price = q.price ?? m.fallbackPrice;
        const chg   = q.change ?? m.fallbackChg;
        const isPos = chg >= 0;
        const priceStr = price >= 10000 ? price.toLocaleString("en-US",{maximumFractionDigits:0})
          : price >= 1000 ? price.toLocaleString("en-US",{minimumFractionDigits:2,maximumFractionDigits:2})
          : price.toFixed(2);

        return(
          <div key={m.ticker} style={{
            background:C.surface,
            border:`1px solid ${C.border}`,
            borderRadius:18,
            marginBottom:12,
            overflow:"hidden",
            boxShadow:"0 2px 12px rgba(0,0,0,0.08)",
            transition:"all 0.18s",
          }}
            onMouseEnter={e=>{e.currentTarget.style.borderColor=C.borderHover;e.currentTarget.style.transform="translateY(-1px)";e.currentTarget.style.boxShadow="0 6px 24px rgba(0,0,0,0.13)";}}
            onMouseLeave={e=>{e.currentTarget.style.borderColor=C.border;e.currentTarget.style.transform="translateY(0)";e.currentTarget.style.boxShadow="0 2px 12px rgba(0,0,0,0.08)";}}>

            <div style={{display:"flex",alignItems:"stretch",gap:0}}>
              {/* Left accent strip */}
              <div style={{width:4,background:isPos?"linear-gradient(180deg,#22c55e,#16a34a)":"linear-gradient(180deg,#ef4444,#dc2626)",flexShrink:0,borderRadius:"18px 0 0 18px"}}/>

              {/* Main content */}
              <div style={{flex:1,padding:"14px 18px 14px 16px"}}>
                <div style={{display:"flex",alignItems:"flex-start",gap:14}}>

                  {/* Rank + badge */}
                  <div style={{display:"flex",flexDirection:"column",alignItems:"center",gap:6,flexShrink:0,width:52}}>
                    {rankMedal(m._rank)}
                    <LogoBadge sym={m.ticker} col={isPos?"#16a34a":"#dc2626"} size={44} radius={10}/>
                  </div>

                  {/* Ticker info + why */}
                  <div style={{flex:1,minWidth:0}}>
                    <div style={{display:"flex",alignItems:"center",gap:8,marginBottom:3,flexWrap:"wrap"}}>
                      <span style={{fontWeight:900,fontSize:16,color:isPos?"#22c55e":"#ef4444",fontFamily:"monospace",letterSpacing:-0.3}}>{m.ticker}</span>
                      <span style={{fontWeight:600,fontSize:12,color:C.muted}}>${priceStr}</span>
                      <span style={{fontSize:11,color:C.muted2}}>{m.name}</span>
                    </div>
                    <div style={{fontSize:12,color:C.muted,lineHeight:1.5,marginBottom:8}}>
                      <span style={{fontWeight:700,color:C.text}}>{isEN?"Why trending? ":"¿Por qué trending? "}</span>{isEN&&m.whyEn?m.whyEn:m.why}
                    </div>
                    <div style={{display:"flex",alignItems:"center",gap:8,flexWrap:"wrap"}}>
                      <span style={{fontSize:12,color:C.muted2}}>💬 <strong style={{color:C.text}}>{m.mentions}</strong> {isEN?"mentions":"menciones"}</span>
                      {/* Badge */}
                      <span style={{
                        background:`${m.badgeColor}18`,
                        color:m.badgeColor,
                        border:`1px solid ${m.badgeColor}44`,
                        borderRadius:20,padding:"2px 10px",fontSize:10,fontWeight:800,letterSpacing:0.4,
                        display:"flex",alignItems:"center",gap:4,
                      }}>{m.badgeIcon} {m.badge}</span>
                    </div>
                    {/* Sentiment bar */}
                    <div style={{display:"flex",alignItems:"center",gap:8,marginTop:8}}>
                      <span style={{fontSize:11,color:"#22c55e",fontWeight:700,minWidth:32}}>▲ {m.bull}%</span>
                      <div style={{flex:1,height:6,borderRadius:20,overflow:"hidden",background:"rgba(239,68,68,0.18)"}}>
                        <div style={{
                          height:"100%",width:`${m.bull}%`,borderRadius:20,
                          background:"linear-gradient(90deg,#22c55e,#16a34a)",
                          transition:"width 0.5s",
                        }}/>
                      </div>
                      <span style={{fontSize:11,color:"#ef4444",fontWeight:700,minWidth:36,textAlign:"right"}}>{m.bear}% ▼</span>
                    </div>
                  </div>

                  {/* Right: sparkline + stats */}
                  <div style={{flexShrink:0,display:"flex",flexDirection:"column",alignItems:"flex-end",gap:4,minWidth:130}}>
                    <div style={{position:"relative"}}>
                      <div style={{position:"absolute",top:2,right:2,fontSize:9,color:C.muted2,fontWeight:600,letterSpacing:0.3}}>24H</div>
                      <MoverSparkline dir={m.sparkDir} chg={chg}/>
                    </div>
                    <div style={{display:"flex",alignItems:"center",gap:4}}>
                      <span style={{fontSize:15}}>{Array.from({length:m.flames},(_,k)=><span key={k}>🔥</span>)}</span>
                      <span style={{fontSize:17,fontWeight:900,color:isPos?"#22c55e":"#ef4444",fontFamily:"monospace",letterSpacing:-0.5}}>
                        {isPos?"+":""}{chg.toFixed(2)}%
                      </span>
                    </div>
                    <div style={{fontSize:10,color:C.muted2}}>Vol. {m.volX}x &nbsp;<strong style={{color:C.muted}}>Vol: {m.volLabel}</strong></div>
                  </div>

                </div>
              </div>
            </div>
          </div>
        );
      })}

      <div style={{textAlign:"center",color:C.muted2,fontSize:11,marginTop:4}}>
        {lang==="en"?"🔄 Real-time prices · Daily editorial curation · nexotradeia.com":"🔄 Precios en tiempo real · Curación editorial diaria · nexotradeia.com"}
      </div>
    </div>
  );
}


