// Afiliados por categoría para mostrar contextualmente en posts
const AFFILIATE_BY_TICKER = (ticker) => {
  const crypto = ["BTC","ETH","SOL","ADA","DOT","MATIC","AVAX","LINK","DOGE","SHIB","BNB","UNI","AAVE"];
  const stocks  = ["AAPL","MSFT","NVDA","TSLA","META","AMZN","GOOGL","AMD","NFLX","COIN","PLTR","SPY","QQQ"];
  if(crypto.includes(ticker)) return AFFILIATES.filter(a=>["kraken","bybit","coinbase"].includes(a.id));
  if(stocks.includes(ticker))  return AFFILIATES.filter(a=>["ibkr","tastytrade","finviz"].includes(a.id));
  return AFFILIATES.slice(0,3);
};

function AffiliateBanner(){
  const [idx, setIdx] = useState(0);
  const aff = AFFILIATES[idx];

  useEffect(()=>{
    const t = setInterval(()=> setIdx(i=>(i+1)%AFFILIATES.length), 6000);
    return ()=> clearInterval(t);
  },[]);

  return(
    <div style={{borderRadius:16,overflow:"hidden",boxShadow:"0 4px 20px rgba(0,0,0,0.15)",marginBottom:10,position:"relative",cursor:"pointer"}}
      onClick={()=>window.open(aff.url,"_blank","noopener")}>

      {/* Fondo oscuro del broker */}
      <div style={{background:aff.bg,padding:"14px 16px"}}>

        {/* Badge + label "Sponsored" */}
        <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:10}}>
          <span style={{fontSize:9,fontWeight:700,color:aff.badgeColor,background:`${aff.badgeColor}22`,borderRadius:20,padding:"2px 8px",letterSpacing:0.8}}>{aff.badge}</span>
          <span style={{fontSize:9,color:"rgba(255,255,255,0.25)",fontWeight:500,letterSpacing:0.5}}>Sponsored</span>
        </div>

        {/* Logo + nombre */}
        <div style={{display:"flex",alignItems:"center",gap:10,marginBottom:8}}>
          <div style={{width:38,height:38,borderRadius:10,background:`${aff.color}22`,border:`1px solid ${aff.color}44`,display:"flex",alignItems:"center",justifyContent:"center",fontSize:20,flexShrink:0}}>
            {aff.logo}
          </div>
          <div>
            <div style={{fontWeight:800,color:"#fff",fontSize:14,letterSpacing:-0.3}}>{aff.name}</div>
            <div style={{fontSize:11,color:aff.color,fontWeight:600}}>{aff.tagline}</div>
          </div>
        </div>

        {/* Sub */}
        <div style={{fontSize:11,color:"rgba(255,255,255,0.5)",marginBottom:12,lineHeight:1.5}}>{aff.sub}</div>

        {/* CTA */}
        <div style={{background:aff.color,borderRadius:9,padding:"9px 14px",textAlign:"center",color:"#fff",fontWeight:800,fontSize:12,letterSpacing:0.2,boxShadow:`0 4px 14px ${aff.color}55`}}>
          {aff.cta}
        </div>
      </div>

      {/* Indicadores de slide */}
      <div style={{display:"flex",justifyContent:"center",gap:5,padding:"8px",background:"rgba(0,0,0,0.4)"}}>
        {AFFILIATES.map((_,i)=>(
          <div key={i} onClick={e=>{e.stopPropagation();setIdx(i);}}
            style={{width: i===idx?18:6,height:6,borderRadius:3,background:i===idx?aff.color:"rgba(255,255,255,0.2)",transition:"all 0.3s",cursor:"pointer"}}/>
        ))}
      </div>
    </div>
  );
}

// ── MOBILE AFFILIATE BANNER (fixed bottom, solo móvil) — compacto 1 línea ────
function MobileAffiliateBanner(){
  const [idx, setIdx] = useState(0);
  const [closed, setClosed] = useState(false);
  const aff = AFFILIATES[idx];

  useEffect(()=>{
    const t = setInterval(()=> setIdx(i=>(i+1)%AFFILIATES.length), 6000);
    return ()=> clearInterval(t);
  },[]);

  // Banner inferior móvil DESACTIVADO: causaba solapamiento/saltos con el menú inferior en Chrome/Safari.
  // (Los afiliados siguen apareciendo como tarjetas dentro del feed.) Para reactivar, quitar este return.
  return null;

  if(closed) return null;

  return(
    <div className="nexo-mobile-affiliate-banner" style={{
      position:"fixed", bottom:"calc(58px + env(safe-area-inset-bottom, 0px))", left:0, right:0,
      zIndex:1200,
      background: aff.bg,
      borderTop:`1px solid ${aff.color}44`,
      borderBottom:`1px solid ${aff.color}22`,
      padding:"8px 10px",
      display:"none", // CSS media query activa en móvil
      alignItems:"center",
      gap:10,
      boxShadow:"0 -4px 20px rgba(0,0,0,0.35)",
    }}>
      <div onClick={()=>window.open(aff.url,"_blank","noopener")} role="button"
        style={{width:34,height:34,borderRadius:9,background:`${aff.color}22`,border:`1px solid ${aff.color}44`,display:"flex",alignItems:"center",justifyContent:"center",fontSize:18,flexShrink:0,cursor:"pointer"}}>
        {aff.logo}
      </div>
      <div onClick={()=>window.open(aff.url,"_blank","noopener")} role="button" style={{flex:1,minWidth:0,cursor:"pointer"}}>
        <div style={{display:"flex",alignItems:"center",gap:6}}>
          <span style={{fontWeight:800,color:"#fff",fontSize:12.5}}>{aff.name}</span>
          <span style={{fontSize:8,color:"rgba(255,255,255,0.35)",letterSpacing:0.5}}>Sponsored</span>
        </div>
        <div style={{fontSize:10.5,color:aff.color,fontWeight:600,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{aff.tagline}</div>
      </div>
      <div onClick={()=>window.open(aff.url,"_blank","noopener")} role="button"
        style={{background:aff.color,borderRadius:8,padding:"7px 10px",color:"#fff",fontWeight:800,fontSize:10.5,whiteSpace:"nowrap",boxShadow:`0 3px 12px ${aff.color}55`,cursor:"pointer",flexShrink:0}}>
        {aff.cta}
      </div>
      <button onClick={()=>setClosed(true)} style={{background:"transparent",border:"none",color:"rgba(255,255,255,0.45)",fontSize:15,cursor:"pointer",padding:"0 2px",lineHeight:1,flexShrink:0}}>✕</button>
    </div>
  );
}

// ── Mini sparkline determinista (verde si sube, rojo si baja) ─────────────────
function MiniSpark({seed=1, up=true, width=48, height=20}){
  const n=10;
  const pts=Array.from({length:n},(_,i)=>{
    const v=Math.sin(seed*0.7+i*0.9)*0.5+Math.cos(i*0.5+seed*0.3)*0.3;
    return v;
  });
  // Inclinar la tendencia según up/down
  const trended=pts.map((v,i)=>v+(up?1:-1)*(i/(n-1))*0.9);
  const min=Math.min(...trended), max=Math.max(...trended), rng=(max-min)||1;
  const col=up?"#16A34A":"#DC2626";
  const d=trended.map((v,i)=>{
    const x=(i/(n-1))*width;
    const y=height-((v-min)/rng)*(height-3)-1.5;
    return `${i===0?"M":"L"}${x.toFixed(1)},${y.toFixed(1)}`;
  }).join(" ");
  return(
    <svg width={width} height={height} style={{flexShrink:0,display:"block"}}>
      <path d={d} fill="none" stroke={col} strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round"/>
    </svg>
  );
}

// ── Modal Paywall — 3 días gratis + beneficios ───────────────────────────────
