// ── WIDGET "MI WATCHLIST" — 5 activos gratis + bloqueados Premium + ilimitado ──
function MiWatchlistWidget({user, isPremium=false, onUpgrade, lang="es", card}){
  const isEN=lang==="en";
  const lp=useContext(PriceCtx);
  const register=useContext(PriceRegisterCtx);
  const FREE_MAX=10;         // tope de activos para cuenta gratis; el 11º pide Premium
  const LS_KEY=`nexo_watchlist_${user?.id||"guest"}`;
  const DEFAULT=["NVDA","AAPL","BTC","META","MSFT","TSLA","ETH","AMZN"];
  const [tickers,setTickers]=useState(()=>{try{const s=JSON.parse(localStorage.getItem(LS_KEY)||"null");return (s&&s.length)?s:DEFAULT;}catch{return DEFAULT;}});
  const [input,setInput]=useState("");
  const [focused,setFocused]=useState(false);
  const [showPaywall,setShowPaywall]=useState(false);
  const [feedback,setFeedback]=useState(null); // null|exists|invalid|added
  const [wlFilter,setWlFilter]=useState("all"); // all|stocks|crypto|top
  const [wlExpanded,setWlExpanded]=useState(false); // máx 10 visibles, flecha para ver el resto
  const WL_CAP=10;
  const CRYPTO_SET=new Set(["BTC","ETH","BNB","XRP","SOL","ADA","DOT","AVAX","MATIC","LINK","LTC","BCH","ATOM","NEAR","UNI","AAVE","DOGE","SHIB","TRX","XLM","ALGO","ICP","FTM","SAND","MANA","CRO","VET","THETA","EOS","ZEC","DASH","XMR","CAKE","COMP","MKR","SNX","YFI","1INCH","RUNE","LUNA","UST","FTT","SRM","SUSHI","BAL","CRV","ZIL","REN","KNC","BAT","OMG","ENJ","CHZ","HOT","TFUEL"]);
  // Gancho: cuenta gratis ve TODAS las filas en vivo menos la ÚLTIMA (esa con candado)
  const visibleCount=isPremium?tickers.length:Math.max(0,tickers.length-1);

  useEffect(()=>{try{localStorage.setItem(LS_KEY,JSON.stringify(tickers));}catch{}},[tickers,LS_KEY]);
  // Registrar SOLO los visibles para precio en vivo (respeta límite Finnhub)
  useEffect(()=>{ register&&register(tickers.slice(0,visibleCount)); },[tickers,visibleCount,register]);

  // Autocompletado: símbolos que empiezan/contienen lo escrito (con nombre de empresa)
  const suggestions = useMemo(()=>{
    const q=input.trim().toUpperCase().replace(/[^A-Z0-9.]/g,"");
    if(!q) return [];
    const pool = (typeof SEARCH_TICKERS_UNIQ!=="undefined" && SEARCH_TICKERS_UNIQ.length) ? SEARCH_TICKERS_UNIQ : Object.keys(TICKER_NAMES);
    const starts=[], contains=[];
    for(const sym of pool){
      if(tickers.includes(sym)) continue;
      if(sym.startsWith(q)) starts.push(sym);
      else if(sym.includes(q)) contains.push(sym);
      if(starts.length>=12) break;
    }
    return [...starts, ...contains].slice(0,8);
  },[input,tickers]);

  const openPaywall=()=>setShowPaywall(true);
  const addSym=(raw)=>{
    const tk=(raw||"").trim().toUpperCase().replace(/[^A-Z0-9.]/g,"");
    if(!tk){return;}
    if(tickers.includes(tk)){setFeedback("exists");setTimeout(()=>setFeedback(null),2000);setInput("");return;}
    // Cuenta gratis: al intentar superar FREE_MAX (el 11º), pide Premium
    if(!isPremium && tickers.length>=FREE_MAX){ setInput(""); setFocused(false); openPaywall(); return; }
    setTickers(prev=>[...prev,tk]);
    setInput(""); setFocused(false); setFeedback("added"); setTimeout(()=>setFeedback(null),1500);
  };
  const addTicker=()=>{ addSym(suggestions[0] && input.trim() ? suggestions[0] : input); };
  const removeTicker=(tk)=>setTickers(prev=>prev.filter(t=>t!==tk));

  const cardStyle = card || {background:"var(--c-surface)",border:"1px solid var(--c-border)",borderRadius:16,padding:0,marginBottom:14,boxShadow:"0 1px 3px rgba(0,0,0,0.06)"};
  const GOLD="#0F4C81";       // azul acero para unificar con el resto de la app
  const GOLD2="#0C3D68";

  // Filter tickers based on tab
  const filteredTickers = useMemo(()=>{
    let list = [...tickers];
    if(wlFilter==="stocks") list = list.filter(t=>!CRYPTO_SET.has(t));
    else if(wlFilter==="crypto") list = list.filter(t=>CRYPTO_SET.has(t));
    else if(wlFilter==="top"){
      list = [...list].sort((a,b)=>{
        const ca=lp[a]?.change??0; const cb=lp[b]?.change??0;
        return cb-ca;
      });
    }
    return list;
  },[tickers,wlFilter,lp,CRYPTO_SET]);

  return(
    <div style={{...cardStyle,padding:0,overflow:"hidden"}}>
      {/* ── Header ── */}
      <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",padding:"12px 14px 10px",borderBottom:"1px solid rgba(15,23,42,0.06)"}}>
        <div style={{display:"flex",alignItems:"center",gap:7}}>
          <span style={{width:7,height:7,borderRadius:"50%",background:"#22c55e",display:"inline-block",animation:"nexo-pulse 2s infinite"}}/>
          <span style={{fontSize:13,fontWeight:800,color:"var(--c-text,#0F172A)",letterSpacing:-0.2}}>{isEN?"My Watchlist":"Mi Watchlist"}</span>
          <span style={{fontSize:10,fontWeight:700,color:"#64748B",background:"rgba(15,23,42,0.05)",borderRadius:20,padding:"2px 7px"}}>{tickers.length}/{isPremium?tickers.length:FREE_MAX}</span>
        </div>
        <span onClick={isPremium?undefined:openPaywall} style={{fontSize:11,fontWeight:700,color:"#1565C0",cursor:"pointer",textDecoration:"none"}}>{isEN?"See all →":"Ver todo →"}</span>
      </div>

      {/* ── Search row ── */}
      <div style={{position:"relative",padding:"9px 12px 8px",borderBottom:"1px solid rgba(15,23,42,0.05)"}}>
        <div style={{display:"flex",gap:6}}>
          <div style={{position:"relative",flex:1,minWidth:0}}>
            <span style={{position:"absolute",left:9,top:"50%",transform:"translateY(-50%)",fontSize:12,color:"#94A3B8",pointerEvents:"none"}}>🔍</span>
            <input value={input}
              onChange={e=>{setInput(e.target.value);setFocused(true);}}
              onFocus={()=>setFocused(true)}
              onBlur={()=>setTimeout(()=>setFocused(false),150)}
              onKeyDown={e=>e.key==="Enter"&&addTicker()}
              placeholder={isEN?"Add ticker (AAPL, BTC...)":"Añadir ticker (AAPL, BTC...)"}
              style={{width:"100%",boxSizing:"border-box",background:"#F8FAFC",border:"1.5px solid #E2EAF4",borderRadius:9,padding:"7px 10px 7px 28px",fontSize:12,color:"#0F172A",outline:"none",fontFamily:"inherit"}}/>
          </div>
          <button onClick={addTicker} style={{background:"#1565C0",border:"none",borderRadius:9,padding:"0 13px",color:"#fff",fontSize:17,fontWeight:700,cursor:"pointer",flexShrink:0,lineHeight:1}}>+</button>
        </div>
        {focused && suggestions.length>0 && (
          <div style={{position:"absolute",top:"calc(100% - 2px)",left:12,right:12,background:"var(--c-surface)",border:"1px solid var(--c-border)",borderRadius:10,boxShadow:"0 12px 32px rgba(0,0,0,0.18)",zIndex:60,overflow:"hidden",maxHeight:240,overflowY:"auto"}}>
            {suggestions.map(sym=>(
              <div key={sym} onMouseDown={e=>{e.preventDefault();addSym(sym);}}
                style={{display:"flex",alignItems:"center",gap:8,padding:"8px 12px",cursor:"pointer",borderBottom:"1px solid rgba(15,23,42,0.04)"}}
                onMouseEnter={e=>e.currentTarget.style.background="rgba(21,101,192,0.06)"}
                onMouseLeave={e=>e.currentTarget.style.background="transparent"}>
                <span style={{fontSize:12.5,fontWeight:800,color:"#0F172A",minWidth:52}}>{sym}</span>
                <span style={{fontSize:11.5,color:"#64748B",flex:1,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{TICKER_NAMES[sym]||""}</span>
                <span style={{fontSize:14,color:"#1565C0",fontWeight:700,flexShrink:0}}>+</span>
              </div>
            ))}
          </div>
        )}
        {feedback&&(
          <div style={{fontSize:10,fontWeight:600,marginTop:4,color:feedback==="exists"?"#D97706":"#16A34A"}}>
            {feedback==="exists"?(isEN?"Already in list":"Ya está en la lista"):(isEN?"✓ Added":"✓ Añadido")}
          </div>
        )}
      </div>

      {/* ── Filter tabs ── */}
      <div style={{display:"flex",gap:0,borderBottom:"1px solid rgba(15,23,42,0.05)",padding:"0 12px"}}>
        {[
          {v:"all",l:"ALL"},
          {v:"stocks",l:"STOCKS"},
          {v:"crypto",l:"CRYPTO"},
          {v:"top",l:"▲ % TODAY"},
        ].map(({v,l})=>(
          <button key={v} onClick={()=>setWlFilter(v)}
            style={{background:"none",border:"none",borderBottom:`2px solid ${wlFilter===v?"#1565C0":"transparent"}`,padding:"7px 10px",fontSize:10,fontWeight:700,letterSpacing:0.4,color:wlFilter===v?"#1565C0":"#94A3B8",cursor:"pointer",whiteSpace:"nowrap",transition:"all 0.12s"}}>
            {l}
          </button>
        ))}
      </div>

      {/* ── Column headers ── */}
      <div style={{display:"grid",gridTemplateColumns:"1fr 58px 80px",gap:0,padding:"5px 14px",borderBottom:"1px solid rgba(15,23,42,0.05)"}}>
        <span style={{fontSize:9.5,fontWeight:700,color:"#94A3B8",letterSpacing:0.6}}>ASSET</span>
        <span style={{fontSize:9.5,fontWeight:700,color:"#94A3B8",letterSpacing:0.6,textAlign:"center"}}>7 DAYS</span>
        <span style={{fontSize:9.5,fontWeight:700,color:"#94A3B8",letterSpacing:0.6,textAlign:"right"}}>LAST · TODAY</span>
      </div>

      {/* ── Rows ── */}
      <div>
        {(wlExpanded?filteredTickers:filteredTickers.slice(0,WL_CAP)).map((tk,i)=>{
          const locked = !isPremium && i===filteredTickers.length-1 && filteredTickers.length>1;
          const live=lp[tk];
          const chg = live?.change ?? null;
          const up = chg!=null ? chg>=0 : (i%3!==1);
          const seed = tk.split("").reduce((a,c)=>a+c.charCodeAt(0),0);

          if(locked){
            return(
              <div key={tk} onClick={openPaywall} style={{display:"grid",gridTemplateColumns:"1fr 58px 80px",alignItems:"center",gap:0,padding:"9px 14px",borderBottom:"1px solid rgba(15,23,42,0.04)",cursor:"pointer",background:"rgba(249,250,251,0.8)",opacity:0.65}}>
                <div style={{display:"flex",alignItems:"center",gap:8}}>
                  <LogoBadge sym={tk} col="#94A3B8" size={32} radius={8}/>
                  <div>
                    <div style={{fontSize:12,fontWeight:800,color:"#0F172A"}}>{tk}</div>
                    <div style={{fontSize:10,color:"#94A3B8",overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap",maxWidth:60}}>{TICKER_NAMES[tk]||""}</div>
                  </div>
                </div>
                <div style={{display:"flex",justifyContent:"center",filter:"blur(4px)",userSelect:"none"}}>
                  <MiniSpark seed={seed} up={true} width={52} height={24}/>
                </div>
                <div style={{textAlign:"right"}}>
                  <span style={{display:"inline-flex",alignItems:"center",gap:3,background:"linear-gradient(135deg,#1565C0,#0F4C81)",color:"#fff",fontSize:9.5,fontWeight:800,borderRadius:20,padding:"4px 9px",whiteSpace:"nowrap",boxShadow:"0 2px 8px rgba(21,101,192,0.35)"}}>🔒 {isEN?"Unlock VIP":"VIP"}</span>
                </div>
              </div>
            );
          }

          const priceStr = live&&live.price!=null ? fmtLivePrice(tk,live.price) : "···";
          const chgStr = chg!=null ? `${up?"▲":"▼"}${Math.abs(chg).toFixed(2)}%` : "";

          return(
            <div key={tk}
              style={{display:"grid",gridTemplateColumns:"1fr 58px 80px",alignItems:"center",gap:0,padding:"8px 14px",borderBottom:"1px solid rgba(15,23,42,0.04)",position:"relative"}}
              onMouseEnter={e=>{const x=e.currentTarget.querySelector('.nx-del');if(x)x.style.opacity='1';}}
              onMouseLeave={e=>{const x=e.currentTarget.querySelector('.nx-del');if(x)x.style.opacity='0';}}>
              {/* Asset col */}
              <div style={{display:"flex",alignItems:"center",gap:8,minWidth:0}}>
                <LogoBadge sym={tk} col="#1565C0" size={32} radius={8}/>
                <div style={{minWidth:0}}>
                  <div style={{fontSize:12,fontWeight:800,color:"var(--c-text,#0F172A)",lineHeight:1.2}}>{tk}</div>
                  <div style={{fontSize:10,color:"#94A3B8",overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap",maxWidth:70}}>{(TICKER_NAMES[tk]||"").split(" ").slice(0,2).join(" ")}</div>
                </div>
                <button className="nx-del" onClick={()=>removeTicker(tk)} title="Remove"
                  style={{opacity:0,transition:"opacity 0.15s",background:"none",border:"none",color:"#CBD5E1",cursor:"pointer",fontSize:12,padding:0,flexShrink:0,marginLeft:2}}>✕</button>
              </div>
              {/* Sparkline col */}
              <div style={{display:"flex",justifyContent:"center"}}>
                <MiniSpark seed={seed} up={up} width={52} height={24}/>
              </div>
              {/* Price/change col */}
              <div style={{textAlign:"right"}}>
                <div style={{fontSize:11.5,fontWeight:700,color:"var(--c-text,#0F172A)",lineHeight:1.3}}>{priceStr}</div>
                {chgStr&&(
                  <span style={{display:"inline-block",fontSize:10,fontWeight:700,color:up?"#fff":"#fff",background:up?"#16A34A":"#DC2626",borderRadius:20,padding:"1px 6px",marginTop:1}}>
                    {chgStr}
                  </span>
                )}
              </div>
            </div>
          );
        })}
      </div>

      {/* ── Ver más / menos (máx 10 visibles) ── */}
      {filteredTickers.length>WL_CAP && (
        <button onClick={()=>setWlExpanded(v=>!v)}
          style={{width:"100%",background:"transparent",border:"none",borderTop:"1px solid rgba(15,23,42,0.05)",padding:"9px",display:"flex",alignItems:"center",justifyContent:"center",gap:6,cursor:"pointer",fontFamily:"inherit",fontSize:11.5,fontWeight:700,color:"#1565C0"}}>
          {wlExpanded?(isEN?"Show less":"Ver menos"):(isEN?`Show ${filteredTickers.length-WL_CAP} more`:`Ver ${filteredTickers.length-WL_CAP} más`)}
          <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="#1565C0" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round" style={{transform:wlExpanded?"rotate(180deg)":"none",transition:"transform .2s"}}><polyline points="6 9 12 15 18 9"/></svg>
        </button>
      )}

      {/* ── Footer ── */}
      {!isPremium&&(
        <div style={{borderTop:"1px solid rgba(15,23,42,0.06)",padding:"10px 14px",display:"flex",alignItems:"center",justifyContent:"space-between",background:"#FAFBFE"}}>
          <span style={{fontSize:10,fontWeight:700,color:"#94A3B8",letterSpacing:0.3}}>{tickers.length} OF {FREE_MAX} USED · FREE PLAN</span>
          <button onClick={openPaywall} style={{background:"none",border:"none",color:"#1565C0",fontSize:11,fontWeight:700,cursor:"pointer",padding:0,whiteSpace:"nowrap"}}>Unlimited with VIP →</button>
        </div>
      )}

      <PaywallModal open={showPaywall} onClose={()=>setShowPaywall(false)} onUpgrade={()=>{setShowPaywall(false);onUpgrade&&onUpgrade();}} lang={lang}/>
    </div>
  );
}

// ── BANNER PREMIUM en el feed (entre posts, cerrable) ────────────────────────
function WatchlistFeedBanner({user, isPremium=false, onUpgrade, lang="es"}){
  const isEN=lang==="en";
  const [closed,setClosed]=useState(()=>{try{return sessionStorage.getItem("nexo-wl-banner-closed")==="1";}catch{return false;}});
  const [showPaywall,setShowPaywall]=useState(false);
  if(isPremium||closed) return null;
  let count=15;
  try{const s=JSON.parse(localStorage.getItem(`nexo_watchlist_${user?.id||"guest"}`)||"null");if(s&&s.length)count=s.length;}catch{}
  const GOLD="#B7791F";
  return(
    <div style={{background:"linear-gradient(135deg,#0F4C81 0%,#0F5E68 100%)",borderRadius:16,padding:"14px 16px",marginBottom:6,position:"relative",overflow:"hidden",display:"flex",alignItems:"center",gap:12}}>
      <button onClick={()=>{setClosed(true);try{sessionStorage.setItem("nexo-wl-banner-closed","1");}catch{}}}
        style={{position:"absolute",top:8,right:10,background:"rgba(255,255,255,0.18)",border:"none",borderRadius:"50%",width:22,height:22,cursor:"pointer",color:"#fff",fontSize:11,display:"flex",alignItems:"center",justifyContent:"center",zIndex:2}}>✕</button>
      <div style={{width:40,height:40,borderRadius:11,background:"rgba(255,255,255,0.14)",display:"flex",alignItems:"center",justifyContent:"center",fontSize:20,flexShrink:0}}>👁</div>
      <div style={{flex:1,minWidth:0,paddingRight:18}}>
        <div style={{fontSize:13.5,fontWeight:800,color:"#fff",letterSpacing:-0.2,marginBottom:2}}>
          {isEN?`You have ${count} assets in your watchlist`:`Tienes ${count} activos en tu watchlist`}
        </div>
        <div style={{fontSize:11.5,color:"rgba(255,255,255,0.82)",lineHeight:1.4}}>
          {isEN?"Unlock all with real-time prices and alerts.":"Desbloquéalos todos con precios en vivo y alertas."}
        </div>
      </div>
      <button onClick={()=>setShowPaywall(true)}
        style={{background:`linear-gradient(135deg,${GOLD},#9C6516)`,border:"none",borderRadius:10,padding:"9px 14px",color:"#fff",fontWeight:800,fontSize:12,cursor:"pointer",flexShrink:0,boxShadow:"0 3px 12px rgba(183,121,31,0.4)",whiteSpace:"nowrap"}}>
        ✦ {isEN?"Try free":"Probar gratis"}
      </button>
      <PaywallModal open={showPaywall} onClose={()=>setShowPaywall(false)} onUpgrade={()=>{setShowPaywall(false);onUpgrade&&onUpgrade();}} lang={lang}/>
    </div>
  );
}

// ── EMAIL CAPTURE — tarjeta en el feed para capturar leads (free/anónimos) ──
function EmailCaptureFeedCard({user, isPremium=false, lang="es"}){
  const isEN=lang==="en";
  const [email,setEmail]=useState("");
  const [done,setDone]=useState(false);
  const [closed,setClosed]=useState(()=>{try{return sessionStorage.getItem("nexo-email-card-closed")==="1";}catch{return false;}});
  // No mostrar a usuarios logueados (ya dieron su email), Premium, ni si ya lo cerró/completó
  if(user||isPremium||closed) return null;
  const submit=()=>{
    if(!email.includes("@")) return;
    try{ supabase.from("newsletter_subscribers").upsert({email, source:"feed_card", created_at:new Date().toISOString()}).then(()=>{}).catch(()=>{}); }catch{}
    try{ fetch("/api/newsletter-welcome",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({email})}).catch(()=>{}); }catch{}
    setDone(true);
  };
  if(done) return(
    <div style={{background:"linear-gradient(135deg,#0F4C81 0%,#0F5E68 100%)",borderRadius:16,padding:"16px 18px",marginBottom:6,textAlign:"center"}}>
      <div style={{fontSize:22,marginBottom:4}}>✅</div>
      <div style={{fontSize:13.5,fontWeight:800,color:"#fff"}}>{isEN?"You're in! Free weekly market signals are on the way.":"¡Listo! Recibirás señales del mercado gratis cada semana."}</div>
    </div>
  );
  return(
    <div style={{background:"linear-gradient(135deg,#0F4C81 0%,#0F5E68 100%)",borderRadius:16,padding:"16px 18px",marginBottom:6,position:"relative",overflow:"hidden"}}>
      <button onClick={()=>{setClosed(true);try{sessionStorage.setItem("nexo-email-card-closed","1");}catch{}}}
        style={{position:"absolute",top:8,right:10,background:"rgba(255,255,255,0.18)",border:"none",borderRadius:"50%",width:22,height:22,cursor:"pointer",color:"#fff",fontSize:11,display:"flex",alignItems:"center",justifyContent:"center",zIndex:2}}>✕</button>
      <div style={{display:"flex",alignItems:"center",gap:10,marginBottom:10,paddingRight:18}}>
        <div style={{width:40,height:40,borderRadius:11,background:"rgba(255,255,255,0.14)",display:"flex",alignItems:"center",justifyContent:"center",fontSize:20,flexShrink:0}}>📧</div>
        <div style={{flex:1,minWidth:0}}>
          <div style={{fontSize:13.5,fontWeight:800,color:"#fff",letterSpacing:-0.2,marginBottom:2}}>
            {isEN?"Free weekly trade signals":"Señales de trading gratis cada semana"}
          </div>
          <div style={{fontSize:11.5,color:"rgba(255,255,255,0.82)",lineHeight:1.4}}>
            {isEN?"Stock & crypto picks, straight to your inbox. No spam.":"Picks de acciones y crypto, directo a tu correo. Sin spam."}
          </div>
        </div>
      </div>
      <div style={{display:"flex",gap:8}}>
        <input value={email} onChange={e=>setEmail(e.target.value)}
          onKeyDown={e=>{if(e.key==="Enter")submit();}}
          type="email" placeholder={isEN?"your@email.com":"tu@email.com"}
          style={{flex:1,minWidth:0,border:"none",borderRadius:10,padding:"10px 14px",fontSize:13,outline:"none",background:"rgba(255,255,255,0.95)",color:"#0f172a",fontFamily:"inherit"}}/>
        <button onClick={submit}
          style={{background:"linear-gradient(135deg,#F59E0B,#B45309)",border:"none",borderRadius:10,padding:"10px 18px",color:"#fff",fontWeight:800,fontSize:13,cursor:"pointer",flexShrink:0,boxShadow:"0 3px 12px rgba(245,158,11,0.4)",whiteSpace:"nowrap"}}>
          {isEN?"Get signals":"Quiero señales"}
        </button>
      </div>
    </div>
  );
}

// ── SHARE VIRAL — invita al mundo (WhatsApp/X/Telegram/Facebook/copiar) ──────
function buildShare(user, lang){
  const isEN = lang==="en";
  const url  = user?.id ? `https://nexotradeia.com?ref=${user.id}` : "https://nexotradeia.com";
  const text = isEN
    ? "📈 Join NexoTrade — the global social trading platform. AI signals, live pre-market, crypto screener & more 🌍"
    : "📈 Únete a NexoTrade — la plataforma social de trading global. Señales IA, pre-market en vivo, screener de crypto y más 🌍";
  return { url, text, isEN };
}

function ShareModal({ open, onClose, user, lang="es" }){
  const [copied,setCopied]=useState(false);
  if(!open) return null;
  const { url, text, isEN } = buildShare(user, lang);
  const enc=encodeURIComponent, eu=enc(url), et=enc(text);
  const nets=[
    {k:"x",   label:"X / Twitter", bg:"#0F172A", icon:"𝕏", href:`https://twitter.com/intent/tweet?text=${et}&url=${eu}`},
  ];
  const copy=()=>{ try{ navigator.clipboard.writeText(url); setCopied(true); setTimeout(()=>setCopied(false),2200);}catch{} };
  return(
    <>
      <div onClick={onClose} style={{position:"fixed",inset:0,background:"rgba(8,13,24,0.6)",backdropFilter:"blur(3px)",zIndex:99990}}/>
      <div style={{position:"fixed",left:"50%",top:"50%",transform:"translate(-50%,-50%)",width:380,maxWidth:"94vw",maxHeight:"90vh",overflowY:"auto",background:C.surface||"#fff",border:`1px solid ${C.border}`,borderRadius:20,boxShadow:"0 30px 80px rgba(0,0,0,0.45)",zIndex:99991}}>
        <div style={{background:"linear-gradient(135deg,#0F4C81,#0F5E68)",padding:"22px 22px 18px",textAlign:"center",position:"relative"}}>
          <button onClick={onClose} style={{position:"absolute",top:12,right:14,background:"rgba(255,255,255,0.18)",border:"none",borderRadius:"50%",width:26,height:26,cursor:"pointer",color:"#fff",fontSize:13}}>✕</button>
          <div style={{fontSize:30,marginBottom:6}}>🌍</div>
          <div style={{fontSize:18,fontWeight:900,color:"#fff",fontFamily:"'Syne',sans-serif",letterSpacing:-0.3}}>{isEN?"Invite the world":"Invita al mundo"}</div>
          <div style={{fontSize:12,color:"rgba(255,255,255,0.85)",marginTop:4,lineHeight:1.4}}>{user?.id?(isEN?"Share your link — earn 1 month Premium free per friend who subscribes.":"Comparte tu link — gana 1 mes Premium gratis por cada amigo que se suscriba."):(isEN?"Share NexoTrade with traders everywhere.":"Comparte NexoTrade con traders de todo el mundo.")}</div>
        </div>
        <div style={{padding:18}}>
          <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:8,marginBottom:12}}>
            {nets.map(n=>(
              <a key={n.k} href={n.href} target="_blank" rel="noopener noreferrer" onClick={onClose}
                style={{display:"flex",alignItems:"center",gap:9,background:n.bg,borderRadius:11,padding:"11px 12px",color:"#fff",fontWeight:800,fontSize:13,textDecoration:"none"}}>
                <span style={{fontSize:16,width:20,textAlign:"center"}}>{n.icon}</span>{n.label}
              </a>
            ))}
          </div>
          <div style={{display:"flex",gap:7,alignItems:"center"}}>
            <div style={{flex:1,minWidth:0,background:C.card2||"#f1f5f9",border:`1px solid ${C.border}`,borderRadius:9,padding:"9px 12px",fontSize:11.5,color:C.muted,fontFamily:"monospace",overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{url.replace("https://","")}</div>
            <button onClick={copy} style={{background:copied?"#16A34A":C.accent,border:"none",borderRadius:9,padding:"9px 15px",color:"#fff",fontWeight:800,fontSize:12.5,cursor:"pointer",whiteSpace:"nowrap",fontFamily:"inherit"}}>{copied?(isEN?"✓ Copied":"✓ Copiado"):(isEN?"Copy":"Copiar")}</button>
          </div>
        </div>
      </div>
    </>
  );
}

// Botón de la barra de navegación (usa share nativo en móvil)
function ShareNavButton({ user, lang="es" }){
  const [open,setOpen]=useState(false);
  const click=async()=>{
    const { url, text } = buildShare(user, lang);
    if(typeof navigator!=="undefined" && navigator.share){
      try{ await navigator.share({title:"NexoTrade", text, url}); return; }catch{}
    }
    setOpen(true);
  };
  return(
    <>
      <button onClick={click} title={lang==="en"?"Share / Invite":"Compartir / Invitar"}
        style={{width:38,height:38,borderRadius:11,border:"1.5px solid rgba(245,158,11,0.45)",background:"rgba(245,158,11,0.08)",cursor:"pointer",display:"flex",alignItems:"center",justifyContent:"center",fontSize:16,transition:"all 0.15s"}}
        onMouseEnter={e=>{e.currentTarget.style.background="rgba(245,158,11,0.18)";}}
        onMouseLeave={e=>{e.currentTarget.style.background="rgba(245,158,11,0.08)";}}>📤</button>
      <ShareModal open={open} onClose={()=>setOpen(false)} user={user} lang={lang}/>
    </>
  );
}

