// ── MENÚ HERRAMIENTAS — mega-dropdown organizado por categorías ───────────────
function ToolsMenu({lang="es", onNavigate, isPremium=false, variant="pill"}){
  const isEN=lang==="en";
  const [open,setOpen]=useState(false);
  const [pos,setPos]=useState({left:0,top:0});
  const ref=useRef(); const btnRef=useRef();
  useEffect(()=>{const h=e=>{if(ref.current&&!ref.current.contains(e.target))setOpen(false);};document.addEventListener("mousedown",h);const sc=()=>setOpen(false);window.addEventListener("resize",sc);return()=>{document.removeEventListener("mousedown",h);window.removeEventListener("resize",sc);};},[]);
  const toggle=()=>{ if(!open&&btnRef.current){const r=btnRef.current.getBoundingClientRect();setPos({left:Math.max(8,Math.min(r.left,(window.innerWidth||1000)-628)),top:r.bottom+6});} setOpen(o=>!o); };
  const go=idx=>{setOpen(false);onNavigate&&onNavigate(idx);};
  const groups=[
    {t:"Calendars", items:[
      [isEN?"Economic Calendar":"Calendario Económico",14],["Earnings",6],["Dividends",15],["IPOs",16],["Holidays",57],["Splits",58],["Futures Expiry",59]]},
    {t:"Calculators", items:[
      ["Pivot Points",46],["Profit",47],["Margin",48],["Forward Rates",50],["Fibonacci",52],["Mortgage",49]]},
    {t:"Currencies", items:[
      [isEN?"Currency Converter":"Conversor",53],["Heat Map",60],["Correlation",54],["Volatility",55]]},
    {t:isEN?"Investing Tools":"Inversión", items:[
      ["Asset Classes",36],["Watchlist",38],["Portfolio Oracle",37],["Alerts",42],["Paper Trading",9],["Fed Rate Monitor",56],[isEN?"Track Record":"Track Record",51]]},
    {t:"Markets", items:[
      ["Live Markets",7],["Pre-Market",45],["Crypto",41],["Commodities",18],["Global Radar",44],["Smart Money",20]]},
    {t:"Education", items:[
      ["Webinars",11],["Academy",12]]},
  ];
  const navBtn = variant==="nav";
  return(
    <div ref={ref} style={{position:"relative",display:"inline-flex",flexShrink:0}}>
      <button ref={btnRef} onClick={toggle} style={navBtn
        ? {display:"flex",alignItems:"center",gap:7,height:52,padding:"0 18px",border:"none",borderBottom:`2.5px solid ${open?"#2196F3":"transparent"}`,background:open?"rgba(33,150,243,0.06)":"transparent",color:open?"#2196F3":"#1A5FAD",fontSize:14,fontWeight:700,cursor:"pointer",whiteSpace:"nowrap",fontFamily:"inherit"}
        : {display:"flex",alignItems:"center",gap:6,background:open?"rgba(15,76,129,0.1)":"transparent",border:`1px solid ${open?"rgba(15,76,129,0.35)":"rgba(15,76,129,0.2)"}`,borderRadius:10,padding:"7px 13px",cursor:"pointer",color:"#0F4C81",fontSize:13,fontWeight:800,fontFamily:"inherit",whiteSpace:"nowrap"}}>
        <NavIco name="tools" size={15}/> {isEN?"Tools":"Herramientas"} <span style={{fontSize:9}}>▾</span>
      </button>
      {open&&(
        <div style={{position:"fixed",left:pos.left,top:pos.top,background:"var(--c-surface)",border:`1px solid ${C.border}`,borderRadius:16,boxShadow:"0 16px 50px rgba(0,0,0,0.22)",zIndex:99995,padding:16,display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(175px,1fr))",gap:"6px 22px",width:"min(620px,94vw)",maxHeight:"min(74vh,580px)",overflowY:"auto"}}>
          {groups.map(g=>(
            <div key={g.t} style={{marginBottom:6}}>
              <div style={{fontSize:11,fontWeight:900,color:"var(--c-text)",letterSpacing:0.3,marginBottom:6,paddingBottom:5,borderBottom:`1px solid ${C.border}`}}>{g.t}</div>
              {g.items.map(([l,idx])=>(
                <button key={l} onClick={()=>go(idx)} style={{display:"block",width:"100%",textAlign:"left",background:"none",border:"none",cursor:"pointer",padding:"6px 4px",fontSize:13,fontWeight:600,color:"#1A5FAD",fontFamily:"inherit",borderRadius:6,transition:"all 0.1s"}}
                  onMouseEnter={e=>{e.currentTarget.style.background="rgba(15,76,129,0.06)";e.currentTarget.style.paddingLeft="8px";}}
                  onMouseLeave={e=>{e.currentTarget.style.background="none";e.currentTarget.style.paddingLeft="4px";}}>→ {l}</button>
              ))}
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

