function NavTickerV4(){
  const lp=useContext(PriceCtx)||{};
  const [cg,setCg]=useState(null);
  useEffect(()=>{
    let c=false;
    const ld=()=>fetch("https://api.coingecko.com/api/v3/simple/price?ids=bitcoin,ethereum&vs_currencies=usd&include_24hr_change=true")
      .then(r=>r.ok?r.json():null).then(j=>{if(!c&&j)setCg(j);}).catch(()=>{});
    ld(); const iv=setInterval(ld,60000); return()=>{c=true;clearInterval(iv);};
  },[]);
  const cgMap={BTC:"bitcoin",ETH:"ethereum"};
  const fmtP=(s,p)=> p>=1000?"$"+Math.round(p).toLocaleString("en-US"):"$"+p.toFixed(2);
  const BASE=[
    {s:"ETH",  p:"$1,800",  chg:0.9},
    {s:"META", p:"$566.41", chg:-0.80},
    {s:"GOLD", p:"$2,320",  chg:-0.2},
    {s:"BTC",  p:"$67,240", chg:1.2},
    {s:"AAPL", p:"$295.38", chg:1.30},
    {s:"NVDA", p:"$202.10", chg:0.84},
    {s:"SPY",  p:"$734.52", chg:1.25},
    {s:"TSLA", p:"$392.32", chg:2.81},
    {s:"MSFT", p:"$387.69", chg:-2.43},
  ];
  const TK=BASE.map(b=>{
    let price=null,chg=null; const cid=cgMap[b.s];
    if(cid&&cg&&cg[cid]&&typeof cg[cid].usd==="number"){price=cg[cid].usd;chg=cg[cid].usd_24h_change;}
    else if(lp[b.s]&&typeof lp[b.s].price==="number"){price=lp[b.s].price;chg=lp[b.s].change;}
    if(price==null) return {s:b.s,p:b.p,c:(b.chg>=0?"\u25B2":"\u25BC")+Math.abs(b.chg).toFixed(2)+"%",up:b.chg>=0};
    const cv=typeof chg==="number"?chg:0;
    return {s:b.s,p:fmtP(b.s,price),c:(cv>=0?"\u25B2":"\u25BC")+Math.abs(cv).toFixed(2)+"%",up:cv>=0};
  });
  return [...TK,...TK].map((it,i)=>(
    <span key={i} style={{display:"inline-flex",alignItems:"center",gap:5,flexShrink:0,padding:"0 16px"}}>
      <span style={{fontWeight:800,color:"rgba(255,255,255,0.85)",fontSize:11.5,letterSpacing:0.2}}>{it.s}</span>
      <span style={{fontSize:11.5,color:"rgba(255,255,255,0.6)"}}>{it.p}</span>
      <span style={{fontSize:11.5,fontWeight:700,color:it.up?"#22C55E":"#F87171"}}>{it.c}</span>
    </span>
  ));
}
function MarketOverview({lang="es"}){
  const isEN=lang==="en";
  const lp=useContext(PriceCtx)||{}; // precios en vivo (cripto vía Binance) para no mostrar valores fijos
  const [d,setD]=useState(null);
  const [loading,setLoading]=useState(true);
  const [region,setRegion]=useState("global");
  const [rd,setRd]=useState({});           // cache por región
  const [rLoading,setRLoading]=useState(false);
  const REGION_TABS=[
    {id:"global",label:"Global",flag:"🌐"},
    {id:"europe",label:"Europe",flag:"🇪🇺"},
    {id:"asia",  label:"Asia-Pacific",flag:"🌏"},
    {id:"latam", label:"Latin America",flag:"🌎"},
  ];
  // Market Overview vía /api/prices (Finnhub) con ETF-proxies + respaldo (nunca vacío)
  const MO_GROUPS = {
    indices:     [["SPY","S&P 500",662],["QQQ","Nasdaq 100",595],["DIA","Dow Jones",447],["IWM","Russell 2000",242]],
    commodities: [["GLD","Gold",243],["SLV","Silver",30],["USO","Oil (WTI)",78],["UNG","Nat Gas",14]],
    crypto:      [["BTC","Bitcoin",67000],["ETH","Ethereum",1800],["SOL","Solana",150]],
  };
  useEffect(()=>{
    let c=false;
    const syms=[...MO_GROUPS.indices,...MO_GROUPS.commodities,...MO_GROUPS.crypto].map(x=>x[0]).join(",");
    const build=(prices)=>{
      const mk=(grp)=>grp.map(([s,n,fb])=>{const q=prices&&prices[s];return {s,n,p:(q&&q.c)||fb,chg:(q&&typeof q.dp==="number")?q.dp:0};});
      return {indices:mk(MO_GROUPS.indices),commodities:mk(MO_GROUPS.commodities),crypto:mk(MO_GROUPS.crypto)};
    };
    const load=()=>{fetch("/api/prices?tickers="+syms).then(r=>r.json()).then(j=>{if(!c){setD(build(j.prices||{}));setLoading(false);}}).catch(()=>{if(!c){setD(build({}));setLoading(false);}});};
    load(); const iv=setInterval(load,60000); return()=>{c=true;clearInterval(iv);};
  },[]);
  // Crypto en vivo via CoinGecko (gratis, sin key, con cambio 24h) — fuente unica para evitar precios fijos/incoherentes
  const [cg,setCg]=useState(null);
  useEffect(()=>{
    let c=false;
    const ld=()=>fetch("https://api.coingecko.com/api/v3/simple/price?ids=bitcoin,ethereum,solana&vs_currencies=usd&include_24hr_change=true")
      .then(r=>r.ok?r.json():null).then(j=>{if(!c&&j)setCg({BTC:j.bitcoin,ETH:j.ethereum,SOL:j.solana});}).catch(()=>{});
    ld(); const iv=setInterval(ld,60000); return()=>{c=true;clearInterval(iv);};
  },[]);
  useEffect(()=>{
    if(region==="global") return;
    let c=false, tries=0, retryTimer=null;
    const load=()=>{
      setRLoading(true);
      fetch("/api/data?type=quotes&set="+region).then(r=>r.json()).then(j=>{
        if(c) return;
        const rows=j.rows||[];
        setRd(prev=>({...prev,[region]:rows}));
        setRLoading(false);
        // Solo datos reales: si la API libre no alcanzó, reintenta pronto (no deja "Sin datos" pegado)
        if(rows.length===0 && tries<5){ tries++; retryTimer=setTimeout(load, 3500); }
      }).catch(()=>{ if(!c){ setRLoading(false); if(tries<5){ tries++; retryTimer=setTimeout(load,3500); } } });
    };
    load(); const iv=setInterval(()=>{tries=0;load();},60000);
    return()=>{c=true;clearInterval(iv);clearTimeout(retryTimer);};
  },[region]);
  const Section=({title,rows})=>(
    <div style={{background:C.surface,border:`1px solid ${C.border}`,borderRadius:16,padding:"14px 16px",boxShadow:"0 2px 14px rgba(15,23,42,0.06)"}}>
      <div style={{fontSize:11,fontWeight:800,color:C.muted2,textTransform:"uppercase",letterSpacing:0.7,marginBottom:10}}>{title}</div>
      {(rows||[]).length===0
        ? <div style={{fontSize:11,color:C.muted2,padding:"6px 0"}}>{loading?"loading…":"—"}</div>
        : rows.map((r,i)=>(
        <div key={r.s} style={{display:"flex",alignItems:"center",justifyContent:"space-between",padding:"7px 0",borderBottom:i<rows.length-1?`1px solid ${C.border}`:"none"}}>
          <span style={{fontSize:12.5,fontWeight:600,color:C.text,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{r.n}</span>
          <div style={{textAlign:"right",flexShrink:0,marginLeft:8}}>
            <span style={{fontSize:12,fontWeight:700,color:C.text,fontFamily:"monospace",marginRight:8}}>{r.p>=1000?r.p.toLocaleString(undefined,{maximumFractionDigits:0}):r.p?.toFixed(2)}</span>
            <span style={{fontSize:12,fontWeight:800,fontFamily:"monospace",color:r.chg>=0?"#16A34A":"#DC2626"}}>{r.chg>=0?"+":""}{(r.chg??0).toFixed(2)}%</span>
          </div>
        </div>
      ))}
    </div>
  );
  const regionRows=region==="global"?null:(rd[region]||[]);
  const Tile=({r})=>(
    <div style={{background:C.surface,border:`1px solid ${C.border}`,borderRadius:16,padding:"14px 16px",boxShadow:"0 2px 14px rgba(15,23,42,0.06)",display:"flex",flexDirection:"column",gap:6}}>
      <span style={{fontSize:12,fontWeight:700,color:C.muted2,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{r.n}</span>
      <div style={{display:"flex",alignItems:"baseline",justifyContent:"space-between"}}>
        <span style={{fontSize:18,fontWeight:800,color:C.text,fontFamily:"monospace"}}>{r.p>=1000?r.p.toLocaleString(undefined,{maximumFractionDigits:0}):r.p?.toFixed(2)}</span>
        <span style={{fontSize:13,fontWeight:800,fontFamily:"monospace",color:r.chg>=0?"#16A34A":"#DC2626"}}>{r.chg>=0?"▲ ":"▼ "}{r.chg>=0?"+":""}{(r.chg??0).toFixed(2)}%</span>
      </div>
    </div>
  );
  const busy=region==="global"?loading:rLoading;
  return(
    <div style={{marginBottom:20}}>
      <div style={{display:"flex",alignItems:"center",gap:8,marginBottom:10,flexWrap:"wrap"}}>
        <h2 style={{margin:0,fontSize:16,fontWeight:800,color:C.text}}>{isEN?"Market Overview":"Resumen del Mercado"}</h2>
        <span style={{fontSize:10.5,fontWeight:700,color:busy?"#F59E0B":"#16A34A"}}>{busy?(isEN?"loading…":"cargando…"):"● "+(isEN?"live":"en vivo")}</span>
      </div>
      <div style={{display:"flex",gap:6,marginBottom:12,flexWrap:"wrap"}}>
        {REGION_TABS.map(t=>{
          const on=region===t.id;
          return(
            <button key={t.id} onClick={()=>setRegion(t.id)} style={{
              display:"flex",alignItems:"center",gap:5,padding:"6px 13px",borderRadius:999,cursor:"pointer",
              fontSize:12.5,fontWeight:700,transition:"all .15s",
              border:`1px solid ${on?C.accent:C.border}`,
              background:on?C.accent:C.surface,
              color:on?"#fff":C.text,
            }}>
              <span style={{fontSize:13}}>{t.flag}</span>{t.label}
            </button>
          );
        })}
      </div>
      {region==="global"
        ? <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(230px,1fr))",gap:12}}>
            <Section title={"Indices"} rows={d?.indices}/>
            <Section title="Crypto" rows={(d?.crypto||[]).map(r=>{const g=cg&&cg[r.s];if(g&&typeof g.usd==="number")return {...r,p:g.usd,chg:(typeof g.usd_24h_change==="number"?g.usd_24h_change:r.chg)};const q=lp[r.s];return (q&&q.price)?{...r,p:q.price,chg:(typeof q.change==="number"?q.change:r.chg)}:r;})}/>
            <Section title="Commodities" rows={d?.commodities}/>
          </div>
        : (regionRows&&regionRows.length===0)
          ? <div style={{fontSize:12.5,color:C.muted2,padding:"14px 0"}}>{isEN?"Updating real data…":"Updating real data…"}</div>
          : <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(150px,1fr))",gap:12}}>
              {(regionRows||[]).map(r=><Tile key={r.s} r={r}/>)}
            </div>}
      <div style={{fontSize:10.5,color:C.muted2,marginTop:8}}>{region==="global" ? (isEN?"Indices & commodities shown via reference ETFs (SPY·QQQ·DIA·IWM) — not the spot index level. Crypto is live.":"Índices y materias primas vía ETF de referencia (SPY·QQQ·DIA·IWM) — no el nivel spot del índice. Cripto en vivo.") : (isEN?"Index proxies via regional ETFs · for reference":"Proxies de índice vía ETF regionales · referencia")}</div>
    </div>
  );
}

