function CommoditySparkline({pts=[],color}){
  if(!pts||pts.length<2) return <span style={{color:"#94a3b8",fontSize:11}}>—</span>;
  const min=Math.min(...pts),max=Math.max(...pts),range=max-min||1;
  const w=80,h=28;
  const coords=pts.map((v,i)=>`${(i/(pts.length-1))*w},${h-((v-min)/range)*(h-4)+2}`).join(" ");
  return(
    <svg width={w} height={h} style={{display:"block"}}>
      <polyline points={coords} fill="none" stroke={color} strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round"/>
    </svg>
  );
}

function CommoditiesPage(){
  const [rows, setRows]       = useState({});
  const [loading, setLoading] = useState(true);
  const [lastUp, setLastUp]   = useState("");
  const [cat, setCat]         = useState("All");
  const [sort, setSort]       = useState("default");

  const fetchPrices = async () => {
    setLoading(true);
    try {
      const r = await fetch("/api/data?type=commodities");
      const d = await r.json();
      if(d.commodities && d.commodities.length > 0){
        const newRows = {};
        d.commodities.forEach(c => {
          newRows[c.id] = {
            price:  c.price,
            daily:  c.daily,
            week:   c.week,
            month:  c.month,
            month3: c.month3,
            ytd:    c.ytd,
            year1:  c.year1,
            spark:  c.spark || [],
          };
        });
        setRows(newRows);
        setLastUp(new Date().toLocaleTimeString("en-US",{hour:"2-digit",minute:"2-digit"}));
      }
    } catch(e){ console.error("Commodities fetch error:",e); }
    setLoading(false);
  };

  useEffect(()=>{ fetchPrices(); const iv=setInterval(fetchPrices,300000); return()=>clearInterval(iv); },[]);

  const fmt=(id,p)=>{
    if(p==null) return "—";
    if(p>=1000) return "$"+p.toLocaleString("en-US",{maximumFractionDigits:2});
    return "$"+p.toFixed(2);
  };
  const fmtPct=(v)=>{
    if(v==null) return <span style={{color:"var(--c-muted2)"}}>—</span>;
    const up=v>=0;
    return <span style={{color:up?"#16a34a":"#dc2626",fontWeight:700}}>{up?"+":""}{v.toFixed(2)}%</span>;
  };

  const cats=["All","Metals","Energy","Agriculture"];
  let list = cat==="All" ? COMMODITIES : COMMODITIES.filter(c=>c.cat===cat);
  if(sort==="gainers") list=[...list].sort((a,b)=>(rows[b.id]?.daily||0)-(rows[a.id]?.daily||0));
  if(sort==="losers")  list=[...list].sort((a,b)=>(rows[a.id]?.daily||0)-(rows[b.id]?.daily||0));

  const COLS = [
    {k:"daily",  l:"Daily"},
    {k:"week",   l:"1 Week"},
    {k:"month",  l:"1 Month"},
    {k:"month3", l:"3 Months"},
    {k:"ytd",    l:"YTD"},
    {k:"year1",  l:"1 Year"},
  ];

  return(
    <div style={{maxWidth:1200,margin:"0 auto",padding:"20px 16px"}}>

      {/* ── HEADER ── */}
      <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",flexWrap:"wrap",gap:12,marginBottom:20}}>
        <div>
          <div style={{display:"flex",alignItems:"center",gap:10}}>
            <h1 style={{margin:0,fontSize:22,fontWeight:900,color:"var(--c-text)"}}>Commodities</h1>
            <span style={{background:"#22c55e",color:"#fff",fontSize:9,fontWeight:800,padding:"2px 8px",borderRadius:10,letterSpacing:1}}>LIVE</span>
          </div>
          <div style={{color:"var(--c-muted2)",fontSize:12,marginTop:2}}>
            {lastUp?`Updated ${lastUp}`:"Loading..."}
            <button onClick={fetchPrices} style={{marginLeft:8,background:"transparent",border:"none",color:"#0F4C81",fontSize:12,cursor:"pointer",padding:0,fontFamily:"inherit"}}>⟳ Refresh</button>
          </div>
        </div>
        {/* Filters */}
        <div style={{display:"flex",gap:6,flexWrap:"wrap"}}>
          {cats.map(c=>(
            <button key={c} onClick={()=>setCat(c)}
              style={{padding:"6px 14px",borderRadius:20,border:`1.5px solid ${cat===c?"#0F4C81":"var(--c-border)"}`,background:cat===c?"#0F4C81":"var(--c-card)",color:cat===c?"#fff":"var(--c-muted2)",fontWeight:700,fontSize:11,cursor:"pointer",fontFamily:"inherit"}}>
              {c==="All"?"All":c==="Metals"?"Metals":c==="Energy"?"Energy":"Agriculture"}
            </button>
          ))}
          <select value={sort} onChange={e=>setSort(e.target.value)}
            style={{padding:"6px 10px",borderRadius:12,border:"1px solid var(--c-border)",background:"var(--c-card)",color:"var(--c-muted2)",fontSize:11,cursor:"pointer",fontFamily:"inherit",outline:"none"}}>
            <option value="default">↕ Default</option>
            <option value="gainers">▲ Top Gainers</option>
            <option value="losers">▼ Top Losers</option>
          </select>
        </div>
      </div>

      {/* ── PERFORMANCE TABLE ── */}
      <div style={{background:"var(--c-card)",border:"1px solid var(--c-border)",borderRadius:16,overflow:"auto",marginBottom:16}}>
        <table style={{width:"100%",borderCollapse:"collapse",minWidth:750}}>
          <thead>
            <tr style={{borderBottom:"2px solid var(--c-border)"}}>
              <th style={{padding:"12px 18px",textAlign:"left",color:"var(--c-muted2)",fontSize:11,fontWeight:700,whiteSpace:"nowrap"}}>Name</th>
              <th style={{padding:"12px 12px",textAlign:"right",color:"var(--c-muted2)",fontSize:11,fontWeight:700}}>Price</th>
              {COLS.map(col=>(
                <th key={col.k} style={{padding:"12px 12px",textAlign:"right",color:"var(--c-muted2)",fontSize:11,fontWeight:700,whiteSpace:"nowrap"}}>{col.l}</th>
              ))}
              <th style={{padding:"12px 12px",textAlign:"center",color:"var(--c-muted2)",fontSize:11,fontWeight:700}}>Chart</th>
            </tr>
          </thead>
          <tbody>
            {loading && (
              <tr><td colSpan={9} style={{padding:"40px",textAlign:"center",color:"var(--c-muted2)",fontSize:13}}>
                Loading performance data...
              </td></tr>
            )}
            {!loading && list.map((c,i)=>{
              const row=rows[c.id];
              const up=row&&row.daily>=0;
              return(
                <tr key={c.id}
                  style={{borderBottom:i<list.length-1?"1px solid var(--c-border)":"none",cursor:"pointer",transition:"background 0.1s"}}
                  onMouseEnter={e=>e.currentTarget.style.background="var(--c-card2)"}
                  onMouseLeave={e=>e.currentTarget.style.background="transparent"}
                  onClick={()=>window.open(`https://finance.yahoo.com/quote/${c.id}`,"_blank")}>
                  {/* Name */}
                  <td style={{padding:"13px 18px"}}>
                    <div style={{display:"flex",alignItems:"center",gap:10}}>
                      <div style={{width:4,height:34,borderRadius:2,background:c.color,flexShrink:0}}/>
                      <div style={{width:38,height:22,borderRadius:5,background:c.color+"18",border:`1px solid ${c.color}40`,display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0}}>
                        <span style={{fontSize:9,fontWeight:800,color:c.color,letterSpacing:0.5,fontFamily:"monospace"}}>{c.ticker}</span>
                      </div>
                      <div>
                        <div style={{color:"var(--c-text)",fontWeight:700,fontSize:13,whiteSpace:"nowrap"}}>{c.name}</div>
                        <div style={{color:"var(--c-muted2)",fontSize:10}}>{c.cat} · {c.unit}</div>
                      </div>
                    </div>
                  </td>
                  {/* Price */}
                  <td style={{padding:"13px 12px",textAlign:"right",fontWeight:800,fontSize:13,fontFamily:"monospace",color:"var(--c-text)",whiteSpace:"nowrap"}}>
                    {fmt(c.id, row?.price)}
                  </td>
                  {/* Period columns */}
                  {COLS.map(col=>(
                    <td key={col.k} style={{padding:"13px 12px",textAlign:"right",fontSize:12,whiteSpace:"nowrap"}}>
                      {fmtPct(row?.[col.k])}
                    </td>
                  ))}
                  {/* Sparkline */}
                  <td style={{padding:"8px 12px",textAlign:"center"}}>
                    <div style={{display:"flex",justifyContent:"center"}}>
                      <CommoditySparkline pts={row?.spark||[]} color={up?"#16a34a":"#dc2626"}/>
                    </div>
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>

      <div style={{textAlign:"center",color:"var(--c-muted2)",fontSize:11,paddingBottom:8}}>
        Historical data via Yahoo Finance · Click any row for full chart · Not financial advice · NexoTrade
      </div>
    </div>
  );
}
// ── FIN COMMODITIES ───────────────────────────────────────────────────────────

function EconCalendarPage({lang="es"}) {
  const isEN = lang==="en";
  const [filter,    setFilter]    = useState("all");
  const [catFilter, setCatFilter] = useState("todas");
  const [events,    setEvents]    = useState(ECON_2026);
  const [loading,   setLoading]   = useState(true);
  const [source,    setSource]    = useState("local");
  const [lastUpd,   setLastUpd]   = useState(null);
  const today = new Date().toISOString().split("T")[0];
  const CATS = ["todas","Inflación","Empleo","Banco Central","Economía","Consumo","Manufactura"];
  const CAT_EN = {"todas":"All","Inflación":"Inflation","Empleo":"Employment","Banco Central":"Central Bank","Economía":"Economy","Consumo":"Consumer","Manufactura":"Manufacturing"};
  const catLabel = c => isEN ? (CAT_EN[c]||c) : (c==="todas"?"Todas":c);
  const evLabel = e => !isEN ? e : (e||"")
    .replace("Inflación","Inflation").replace("Manufactura","Manufacturing")
    .replace("Nóminas No Agrícolas","Nonfarm Payrolls").replace("Tasa de Desempleo","Unemployment Rate")
    .replace("IPC / CPI","CPI").replace("Ventas al Por Menor","Retail Sales")
    .replace("Decisión de Tasas","Rate Decision").replace("Confianza del Consumidor","Consumer Confidence")
    .replace("PIB EEUU","US GDP").replace("(avance)","(advance)")
    .replace("(Abr)","(Apr)").replace("(Ago)","(Aug)");
  const IMP   = {high:{bg:"#FEF2F2",color:C.bear,label:isEN?"High":"Alta"},med:{bg:"#FFFBEB",color:C.gold,label:isEN?"Med":"Media"},low:{bg:"#F0FDF4",color:C.bull,label:isEN?"Low":"Baja"}};
  const fmtDate = d => new Date(d+"T12:00:00").toLocaleDateString(isEN?"en-US":"es-ES",{weekday:"short",day:"numeric",month:"short"});

  useEffect(()=>{
    fetch("/api/data?type=econ")
      .then(r=>r.json())
      .then(d=>{
        if(d.events && d.events.length > 5){
          setEvents(d.events);
          setSource(d.source==="fmp" ? "live" : "local");
          setLastUpd(new Date().toLocaleTimeString(isEN?"en-US":"es-ES",{hour:"2-digit",minute:"2-digit"}));
        }
      })
      .catch(()=>{})
      .finally(()=>setLoading(false));
  },[]);

  const rows = events.filter(e=>{
    const past = e.date < today;
    if(filter==="upcoming" && past) return false;
    if(filter==="past"     && !past) return false;
    if(catFilter!=="todas" && e.cat!==catFilter) return false;
    return true;
  });

  return(
    <div style={{maxWidth:860,margin:"0 auto"}}>
      <div style={{background:C.card,borderRadius:16,padding:"20px 24px",marginBottom:16,boxShadow:C.shadow,border:`1px solid ${C.border}`}}>
        <div style={{display:"flex",alignItems:"center",gap:12,marginBottom:14}}>
          <span style={{fontSize:30}}>📅</span>
          <div style={{flex:1}}>
            <div style={{display:"flex",alignItems:"center",gap:8}}>
              <div style={{fontSize:20,fontWeight:800,color:C.text}}>{isEN?"Economic Calendar":"Calendario Económico"}</div>
              {source==="live"
                ? <span style={{fontSize:10,fontWeight:700,color:C.bull,background:C.bullBg,borderRadius:10,padding:"2px 8px"}}>{isEN?"● LIVE":"● EN VIVO"}</span>
                : <span style={{fontSize:10,fontWeight:700,color:C.muted2,background:C.card2,borderRadius:10,padding:"2px 8px",border:`1px solid ${C.border}`}}>{isEN?"LOCAL":"MODO LOCAL"}</span>
              }
            </div>
            <div style={{fontSize:12,color:C.muted}}>
              {isEN?"Macro events that move the markets — FOMC · CPI · NFP · GDP · PCE":"Eventos macro que mueven los mercados — FOMC · CPI · NFP · GDP · PCE"}
              {lastUpd && <span style={{marginLeft:8,color:C.muted2}}>· {isEN?"Updated":"Actualizado"} {lastUpd}</span>}
            </div>
          </div>
          {loading && <span style={{fontSize:11,color:C.muted,background:C.card2,borderRadius:8,padding:"3px 9px",border:`1px solid ${C.border}`}}>{isEN?"⏳ Loading…":"⏳ Cargando…"}</span>}
        </div>
        <div style={{display:"flex",gap:6,flexWrap:"wrap"}}>
          {[{k:"all",l:isEN?"All":"Todos"},{k:"upcoming",l:isEN?"📌 Upcoming":"📌 Próximos"},{k:"past",l:isEN?"Past":"Pasados"}].map(({k,l})=>(
            <button key={k} onClick={()=>setFilter(k)} style={{background:filter===k?C.accent:"transparent",color:filter===k?"#fff":C.muted,border:`1.5px solid ${filter===k?C.accent:C.border}`,borderRadius:20,padding:"5px 13px",fontSize:12,fontWeight:600,cursor:"pointer",transition:"all 0.15s"}}>{l}</button>
          ))}
          <span style={{width:1,background:C.border,margin:"0 2px"}}/>
          {CATS.map(cat=>(
            <button key={cat} onClick={()=>setCatFilter(cat)} style={{background:catFilter===cat?C.purpleBg:"transparent",color:catFilter===cat?C.purple:C.muted,border:`1.5px solid ${catFilter===cat?C.purple+"55":C.border}`,borderRadius:20,padding:"5px 13px",fontSize:12,fontWeight:600,cursor:"pointer",transition:"all 0.15s"}}>{catLabel(cat)}</button>
          ))}
        </div>
      </div>

      <div style={{display:"flex",gap:14,marginBottom:12,padding:"0 2px",alignItems:"center",justifyContent:"space-between"}}>
        <div style={{display:"flex",gap:14}}>
          {Object.entries(IMP).map(([k,v])=>(
            <span key={k} style={{display:"flex",alignItems:"center",gap:5,fontSize:11,color:C.muted}}>
              <span style={{width:8,height:8,borderRadius:"50%",background:v.color}}/>
              {v.label} {isEN?"importance":"importancia"}
            </span>
          ))}
        </div>
        <span style={{fontSize:11,color:C.muted2}}>{rows.length} {isEN?"events":"eventos"}</span>
      </div>

      <div className="nexo-scroll-x" style={{borderRadius:12}}>
      <div style={{minWidth:440,display:"flex",flexDirection:"column",gap:8}}>
        {rows.length===0 && <div style={{textAlign:"center",padding:"40px 0",color:C.muted}}>{isEN?"No events for this filter.":"Sin eventos con ese filtro."}</div>}
        {rows.map((ev,i)=>{
          const past    = ev.date < today;
          const isToday = ev.date === today;
          const imp     = IMP[ev.imp] || IMP.low;
          const hasActual = ev.actual && ev.actual !== "—" && ev.actual !== null;
          return(
            <div key={i} style={{background:isToday?"rgba(15,76,129,0.03)":C.card,border:`1px solid ${isToday?C.accent+"44":C.border}`,borderLeft:`4px solid ${past&&!hasActual?C.muted2:imp.color}`,borderRadius:12,padding:"14px 20px",opacity:past&&!hasActual?0.55:1,display:"grid",gridTemplateColumns:"140px 1fr 150px",alignItems:"center",gap:16,boxShadow:isToday?C.shadowGlow:"none",transition:"opacity 0.2s"}}>
              <div>
                <div style={{fontSize:12,fontWeight:700,color:past?C.muted:C.text}}>{fmtDate(ev.date)}</div>
                <div style={{fontSize:10,color:C.muted2,marginTop:2}}>{ev.country} {catLabel(ev.cat)}</div>
                {ev.time && <div style={{fontSize:10,color:C.muted2,marginTop:1}}>🕗 {ev.time} ET</div>}
              </div>
              <div>
                <div style={{fontSize:14,fontWeight:700,color:past&&!hasActual?C.muted:C.text}}>{evLabel(ev.event)}</div>
                <div style={{display:"flex",gap:6,marginTop:4,alignItems:"center",flexWrap:"wrap"}}>
                  <span style={{fontSize:10,fontWeight:700,color:imp.color,background:imp.bg,borderRadius:10,padding:"2px 8px"}}>{imp.label}</span>
                  {isToday && <span style={{fontSize:10,fontWeight:700,color:C.accent,background:C.accentDim,borderRadius:10,padding:"2px 8px"}}>{isEN?"TODAY":"HOY"}</span>}
                  {hasActual && <span style={{fontSize:10,fontWeight:700,color:C.bull,background:C.bullBg,borderRadius:10,padding:"2px 8px"}}>{isEN?"✓ RELEASED":"✓ PUBLICADO"}</span>}
                  {ev.cat==="Banco Central" && <span style={{fontSize:10,fontWeight:700,color:"#0F5E68",background:"rgba(15,94,104,0.09)",borderRadius:10,padding:"2px 8px"}}>🏦 FED</span>}
                </div>
              </div>
              <div style={{textAlign:"right"}}>
                {hasActual && (
                  <div style={{fontSize:14,fontWeight:800,color:C.bull,marginBottom:4}}>
                    <span style={{fontSize:10,color:C.muted2,fontWeight:500,display:"block",marginBottom:1}}>{isEN?"ACTUAL":"ACTUAL"}</span>
                    {ev.actual}
                  </div>
                )}
                {ev.est!=="—" && !hasActual && <div style={{fontSize:11,color:past?C.muted:C.accent,marginBottom:2}}><b>Est:</b> {ev.est}</div>}
                {ev.prev!=="—" && <div style={{fontSize:11,color:C.muted}}><b>{isEN?"Prev:":"Ant:"}</b> {ev.prev}</div>}
              </div>
            </div>
          );
        })}
      </div>{/* /nexo-scroll-x inner */}
      </div>{/* /nexo-scroll-x */}
      <div style={{textAlign:"center",padding:"16px 0",fontSize:11,color:C.muted2}}>
        {source==="live" ? isEN?"⚡ Real-time data via Financial Modeling Prep (FMP)":"⚡ Datos en tiempo real via Financial Modeling Prep (FMP)" : isEN?"📋 Base data — add FMP_API_KEY in Vercel for real-time":"📋 Datos base — agrega FMP_API_KEY en Vercel para tiempo real"}
        {" · "}{isEN?"Sources":"Fuentes"}: Federal Reserve, BLS, BEA
      </div>
    </div>
  );
}

