function DividendCalendarPage({lang="es"}) {
  const isEN = lang==="en";
  const curYear = new Date().getFullYear();
  const [yearTab, setYearTab] = useState(String(curYear));
  const [divs,    setDivs]    = useState(DIV_FALLBACK);
  const [loading, setLoading] = useState(true);
  const [source,  setSource]  = useState("local");
  const [sector,  setSector]  = useState("todos");
  const [search,  setSearch]  = useState("");
  const today = new Date().toISOString().split("T")[0];
  const sectors = ["todos","Tecnología","Salud","Consumo","Energía","Telecomunicaciones","Finanzas","REITs","Utilities","BDC/Yield"];

  const fetchDivs = (year) => {
    setLoading(true);
    // Para años futuros usamos fallback con fechas proyectadas (+N años)
    const diffYears = parseInt(year) - curYear;
    fetch(`/api/data?type=dividends&year=${year}`)
      .then(r=>r.json())
      .then(d=>{
        if(d.dividends && d.dividends.length > 3){
          // Mezclar con DIV_FALLBACK para completar yield/precio que FMP no devuelve
          const merged = DIV_FALLBACK.map(fb=>{
            const live = d.dividends.find(x=>x.ticker===fb.ticker);
            return live ? {...fb, exDate:live.exDate||fb.exDate, payDate:live.payDate||fb.payDate, quarterly:live.quarterly!=="—"?live.quarterly:fb.quarterly} : fb;
          });
          setDivs(merged);
          setSource("live");
        } else if(diffYears > 0){
          // Proyectar fechas del fallback sumando años
          const projected = DIV_FALLBACK.map(fb=>({
            ...fb,
            exDate:  fb.exDate  ? fb.exDate.replace(/^\d{4}/,  String(parseInt(fb.exDate.slice(0,4))+diffYears))  : fb.exDate,
            payDate: fb.payDate ? fb.payDate.replace(/^\d{4}/, String(parseInt(fb.payDate.slice(0,4))+diffYears)) : fb.payDate,
          }));
          setDivs(projected);
          setSource("projected");
        } else {
          setDivs(DIV_FALLBACK);
          setSource("local");
        }
      })
      .catch(()=>{ setDivs(DIV_FALLBACK); setSource("local"); })
      .finally(()=>setLoading(false));
  };

  useEffect(()=>{ fetchDivs(yearTab); },[yearTab]);

  const q = search.trim().toLowerCase();
  const rows = divs.filter(d=> (sector==="todos" || d.sector===sector) && (!q || d.ticker.toLowerCase().includes(q) || (d.name||"").toLowerCase().includes(q)));
  const soon = (dateStr) => dateStr && dateStr >= today && new Date(dateStr)-new Date(today) < 30*864e5;
  const fmt  = d => d ? new Date(d+"T12:00:00").toLocaleDateString(isEN?"en-US":"es-ES",{day:"numeric",month:"short"}) : "—";
  const SEC_EN = {"todos":"All","Tecnología":"Technology","Salud":"Health","Consumo":"Consumer","Energía":"Energy","Telecomunicaciones":"Telecom","Finanzas":"Financials","Utilities":"Utilities","REITs":"REITs","ETF":"ETF","BDC/Yield":"BDC/Yield"};
  const secLabel = s => isEN ? (SEC_EN[s]||s) : (s==="todos"?"Todos":s);

  return(
    <div style={{maxWidth:900,margin:"0 auto"}}>
      <div style={{background:C.card,borderRadius:16,padding:"20px 24px",marginBottom:16,boxShadow:C.shadow,border:`1px solid ${C.border}`}}>
        <div style={{display:"flex",alignItems:"center",gap:12,marginBottom:12}}>
          <span style={{fontSize:30}}>💰</span>
          <div style={{flex:1}}>
            <div style={{display:"flex",alignItems:"center",gap:8,flexWrap:"wrap"}}>
              <div style={{fontSize:20,fontWeight:800,color:C.text}}>{isEN?"Dividend Calendar":"Calendario de Dividendos"}</div>
              {source==="live"      && <span style={{fontSize:10,fontWeight:700,color:C.bull,background:C.bullBg,borderRadius:10,padding:"2px 8px"}}>● LIVE</span>}
              {source==="projected" && <span style={{fontSize:10,fontWeight:700,color:"#F59E0B",background:"rgba(245,158,11,0.1)",borderRadius:10,padding:"2px 8px"}}>{isEN?"PROJECTED":"PROYECTADO"}</span>}
              {source==="local"     && <span style={{fontSize:10,fontWeight:700,color:C.muted2,background:C.card2,borderRadius:10,padding:"2px 8px",border:`1px solid ${C.border}`}}>CURATED</span>}
            </div>
            <div style={{fontSize:12,color:C.muted,marginTop:2}}>{isEN?"Upcoming ex-dividend dates and payouts of major companies":"Próximas fechas ex-dividendo y pagos de las principales empresas"}</div>
          </div>
          {loading && <span style={{fontSize:11,color:C.muted,background:C.card2,borderRadius:8,padding:"3px 9px"}}>{isEN?"Updating...":"Actualizando..."}</span>}
        </div>
        {/* Year tabs */}
        <div style={{display:"flex",gap:8,marginBottom:12,flexWrap:"wrap"}}>
          {[String(curYear), String(curYear+1), String(curYear+2)].map(y=>(
            <button key={y} onClick={()=>setYearTab(y)}
              style={{padding:"5px 16px",borderRadius:20,border:`2px solid ${yearTab===y?C.bull:C.border}`,background:yearTab===y?C.bull+"18":"transparent",cursor:"pointer",transition:"all 0.15s"}}>
              <span style={{fontSize:13,fontWeight:800,color:yearTab===y?C.bull:C.muted}}>{y}</span>
              {y!==String(curYear) && <span style={{fontSize:10,color:yearTab===y?C.bull:C.muted2,fontWeight:600,marginLeft:4}}>{isEN?"Proj.":"Proy."}</span>}
            </button>
          ))}
        </div>
        <div style={{position:"relative",marginBottom:10}}>
          <span style={{position:"absolute",left:12,top:"50%",transform:"translateY(-50%)",fontSize:13,color:C.muted2}}>🔍</span>
          <input value={search} onChange={e=>setSearch(e.target.value)} placeholder={isEN?"Search ticker or company…":"Buscar ticker o empresa…"}
            style={{width:"100%",boxSizing:"border-box",background:C.card2,border:`1px solid ${C.border}`,borderRadius:10,padding:"9px 12px 9px 32px",fontSize:13,color:C.text,outline:"none",fontFamily:"inherit"}}/>
        </div>
        <div style={{display:"flex",gap:6,flexWrap:"wrap"}}>
          {sectors.map(s=>(
            <button key={s} onClick={()=>setSector(s)} style={{background:sector===s?C.bull+"22":"transparent",color:sector===s?C.bull:C.muted,border:`1.5px solid ${sector===s?C.bull+"44":C.border}`,borderRadius:20,padding:"5px 13px",fontSize:12,fontWeight:600,cursor:"pointer",transition:"all 0.15s"}}>{secLabel(s)}</button>
          ))}
        </div>
      </div>

      <div className="nexo-scroll-x" style={{borderRadius:16}}>
      <div style={{minWidth:530,background:C.card,borderRadius:16,overflow:"hidden",boxShadow:C.shadow,border:`1px solid ${C.border}`}}>
        <div style={{display:"grid",gridTemplateColumns:"90px 1fr 90px 90px 80px 80px",gap:0,background:C.card2,borderBottom:`1px solid ${C.border}`,padding:"10px 20px"}}>
          {(isEN?["Ticker","Company","Ex-Date","Payout","Quarterly","Yield"]:["Ticker","Empresa","Ex-Fecha","Pago","Trimestral","Yield"]).map(h=>(
            <div key={h} style={{fontSize:10,fontWeight:700,color:C.muted2,letterSpacing:0.5}}>{h.toUpperCase()}</div>
          ))}
        </div>
        {rows.map((d,i)=>{
          const isSoon = soon(d.exDate);
          return(
            <div key={i} style={{display:"grid",gridTemplateColumns:"90px 1fr 90px 90px 80px 80px",gap:0,padding:"13px 20px",borderBottom:`1px solid ${C.border}`,background:isSoon?"rgba(22,163,74,0.03)":"transparent",transition:"background 0.15s"}}
              onMouseEnter={e=>e.currentTarget.style.background=isSoon?"rgba(22,163,74,0.06)":C.card2}
              onMouseLeave={e=>e.currentTarget.style.background=isSoon?"rgba(22,163,74,0.03)":"transparent"}>
              <div style={{fontWeight:800,fontSize:13,color:C.accent}}>{d.ticker}</div>
              <div>
                <div style={{fontSize:13,fontWeight:600,color:C.text}}>{d.name}</div>
                <div style={{fontSize:10,color:C.muted2,marginTop:1}}>{secLabel(d.sector)}</div>
              </div>
              <div>
                <div style={{fontSize:13,fontWeight:isSoon?700:500,color:isSoon?C.bull:C.text}}>{fmt(d.exDate)}</div>
                {isSoon && <div style={{fontSize:9,color:C.bull,fontWeight:700,marginTop:1}}>{_EN()?"UPCOMING":"PRÓXIMO"}</div>}
              </div>
              <div style={{fontSize:13,color:C.muted}}>{fmt(d.payDate)}</div>
              <div style={{fontSize:13,fontWeight:600,color:C.text}}>${d.quarterly}</div>
              <div style={{fontSize:13,fontWeight:700,color:parseFloat(d.yield)>=4?C.bull:C.text}}>{parseFloat(d.yield).toFixed(2)}%</div>
            </div>
          );
        })}
      </div>
      </div>{/* /nexo-scroll-x */}
      <div style={{textAlign:"center",padding:"14px 0",fontSize:11,color:C.muted2}}>
        {source==="live" ? (isEN?"⚡ Live data via FMP":"⚡ Datos via FMP en tiempo real") : source==="projected" ? (isEN?`📅 Projected dates for ${yearTab} based on history — may vary`:`📅 Fechas proyectadas para ${yearTab} basadas en historial — pueden variar`) : (isEN?"📋 Curated list · Ex-date is the last day to buy and receive the dividend":"📋 Lista curada · Ex-fecha es el último día para comprar y recibir el dividendo")}
      </div>
    </div>
  );
}

